sp_widget.client_script:
function() {
  /* PTAG Global Control - invisible mechanics widget (no UI).
     1) Marks document.body with .ptag-hub as the portal-wide styling hook.
        Removal on $destroy intentionally omitted: the marker is portal-wide.
     2) Hides the usage-insights control on every page. Pattern replicated
        1:1 from the live installer widget 'agent_console_portal_control'
        (Agent Console scope, read-only reference).
     3) De-scopes this widget's own compiled css FIELD: SP prefixes every
        rule with .v<sys_id>, which can never match our body.ptag-hub
        component selectors, so the block is re-injected verbatim without
        the prefix as <style id="ptag-components-css">. */
  var c = this;

  function mark() {
    try { document.body.classList.add('ptag-hub'); } catch (e) {}
  }
  c.$onInit = mark;
  mark(); // classList.add is idempotent; run immediately as well

  /* --- usage-insights hide (exact agent_console_portal_control pattern) --- */
  var SEL = 'button.uxa-analytics-btn, .uxa-analytics-btn, [aria-label="Open usage insights"], [aria-label="Minimize usage insights"]';
  function hide() {
    try {
      var els = document.querySelectorAll(SEL);
      for (var i = 0; i < els.length; i++) { els[i].style.setProperty('display', 'none', 'important'); }
    } catch (e) {}
  }
  hide();
  var n = 0;
  var iv = setInterval(function () { hide(); if (++n >= 50) { clearInterval(iv); } }, 200); // bounded ~10s sweep
  try {
    var mo = new MutationObserver(hide);
    mo.observe(document.documentElement, { childList: true, subtree: true });
    setTimeout(function () { mo.disconnect(); }, 20000);
  } catch (e) {}

  /* --- SKIN:GLOBAL-COMPONENTS de-scoper --------------------------------
     The css FIELD compiles to .v<sys_id>-scoped selectors (inert for
     body-level component rules). Re-inject the compiled block with the
     scope prefix stripped; id-guarded so it runs once per page load. */
  var VTAG = '.v671395f4931ec3d04639f8597bba1061';
  function unscope() {
    try {
      if (document.getElementById('ptag-components-css')) { return true; }
      var styles = document.querySelectorAll('style');
      for (var i = 0; i < styles.length; i++) {
        var t = styles[i].textContent || '';
        if (t.indexOf(VTAG + ' ') === -1) { continue; }
        var el = document.createElement('style');
        el.id = 'ptag-components-css';
        el.textContent = t.split(VTAG + ' ').join('');
        document.head.appendChild(el);
        return true;
      }
    } catch (e) {}
    return false;
  }
  if (!unscope()) {
    var un = 0;
    var uiv = setInterval(function () { if (unscope() || ++un >= 50) { clearInterval(uiv); } }, 200);
  }
}

sp_widget.css:
/* PTAG Global Control - DOM tweaks only, no UI in template. */
/* == MECHANICS (do not remove) =========================================== */
/* Belt-and-braces static hide (the client script is the reliable path).    */
button.uxa-analytics-btn, .uxa-analytics-btn { display: none !important; }

/* == SKIN:GLOBAL-BASE ==================================================== */
/* Design pass: portal-wide base rules land here (scope under body.ptag-hub) */

/* == SKIN:GLOBAL-COMPONENTS ============================================== */
/* Design pass: shared component rules land here                            */

/* == I3-COMPONENTS START (skin pass; lives inside SKIN:GLOBAL-COMPONENTS) == */
body.ptag-hub .pt-shell--narrow { max-width: 720px; }
body.ptag-hub .pt-shell--form { max-width: 860px; }
body.ptag-hub .pt-btn--pill { border-radius: var(--pt-r-full); }
body.ptag-hub .pt-group-h { font-size: var(--pt-fs-xs); font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: var(--pt-text-mute); margin: 26px 0 12px; }
body.ptag-hub .pt-group-h:first-child { margin-top: 0; }
body.ptag-hub .pt-pipe__row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 8px 0; border-top: 1px solid var(--pt-stroke); }
body.ptag-hub .pt-pipe__row:first-child { border-top: 0; }
body.ptag-hub .pt-pipe__n { font-family: var(--pt-font-display); font-weight: 700; font-size: 18px; color: var(--pt-text-hi); font-variant-numeric: tabular-nums; }
body.ptag-hub .pt-iconbtn { width: 36px; height: 36px; padding: 0; display: inline-flex; align-items: center; justify-content: center; border-radius: 10px; background: var(--pt-surface-2); border: 1px solid var(--pt-stroke); color: var(--pt-text-mute); cursor: pointer; transition: all var(--pt-dur-fast) var(--pt-ease); }
body.ptag-hub .pt-iconbtn:hover { color: var(--pt-text-hi); border-color: var(--pt-stroke-strong); background: var(--pt-surface-3); }
body.ptag-hub .pt-icon-tile { box-shadow: 0 0 22px -4px rgba(99, 223, 78, 0.28); }
body.ptag-hub .pt-icon-tile--cyan { box-shadow: 0 0 22px -4px rgba(0, 174, 239, 0.28); }
body.ptag-hub .pt-icon-tile--violet { box-shadow: 0 0 22px -4px rgba(167, 139, 250, 0.28); }
body.ptag-hub .pt-alert { border: 1px solid rgba(248, 113, 113, 0.4); background: rgba(248, 113, 113, 0.08); border-radius: var(--pt-r-md); padding: 12px 16px; margin-bottom: var(--pt-sp-5); }
body.ptag-hub .pt-alert p { margin: 0; color: var(--pt-state-declined); font-size: var(--pt-fs-sm); font-weight: 600; }
/* == I3-COMPONENTS END == */

/* == I5-REFPICKER START (lives inside SKIN:GLOBAL-COMPONENTS) ============ */
/* Closed-state reference control - reads like a .pt-field input */
body.ptag-hub .pt-refselect { position: relative; display: block; width: 100%; }
body.ptag-hub .pt-refselect__btn {
  display: block; width: 100%; text-align: left; cursor: pointer; min-height: 47px;
  background: var(--pt-surface-2); color: var(--pt-text-hi);
  border: 1px solid var(--pt-stroke); border-radius: var(--pt-r-md);
  padding: 12px 76px 12px 15px; font-family: var(--pt-font-ui); font-size: var(--pt-fs-base);
  transition: border-color var(--pt-dur-fast) var(--pt-ease), box-shadow var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-refselect__btn:hover { border-color: var(--pt-stroke-strong); }
body.ptag-hub .pt-refselect__btn:focus,
body.ptag-hub .pt-refselect__btn:focus-visible {
  border-color: var(--pt-green); box-shadow: var(--pt-focus-ring); outline: none;
}
body.ptag-hub .pt-refselect__ph { color: var(--pt-text-faint); }
body.ptag-hub .pt-refselect__val { color: var(--pt-text-hi); }
body.ptag-hub .pt-refselect__chev {
  position: absolute; right: 15px; top: 50%; transform: translateY(-50%);
  color: var(--pt-text-mute); pointer-events: none;
}
body.ptag-hub .pt-refselect__clear {
  position: absolute; right: 40px; top: 50%; transform: translateY(-50%);
  display: inline-flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; padding: 0; border: 0; border-radius: var(--pt-r-sm);
  background: transparent; color: var(--pt-text-mute); cursor: pointer;
  transition: background var(--pt-dur-fast) var(--pt-ease), color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-refselect__clear:hover { background: var(--pt-surface-3); color: var(--pt-text-hi); }
body.ptag-hub .pt-refselect__clear:focus-visible { box-shadow: var(--pt-focus-ring); outline: none; }
body.ptag-hub .pt-field.has-error .pt-refselect__btn { border-color: var(--pt-state-declined); }

/* Modal reference picker */
body.ptag-hub .pt-modal-backdrop {
  position: fixed; inset: 0; z-index: 200;
  background: rgba(4, 8, 16, 0.72);
  -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
  display: flex; align-items: center; justify-content: center;
  padding: 16px;
  animation: pt-modal-fade 180ms var(--pt-ease) both;
}
body.ptag-hub .pt-modal {
  /* SASS-safe min(560px, 92vw): SP's SCSS evaluates min() (emitted 92vw,
     dropping the cap), so express it as width + max-width */
  width: 92vw; max-width: 560px; max-height: 76vh;
  background: var(--pt-surface-1); border: 1px solid var(--pt-stroke-strong);
  border-radius: var(--pt-r-xl); box-shadow: var(--pt-shadow-3);
  display: flex; flex-direction: column; overflow: hidden;
  animation: pt-modal-rise 180ms var(--pt-ease) both;
}
@keyframes pt-modal-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes pt-modal-rise {
  from { opacity: 0; transform: translateY(14px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
body.ptag-hub .pt-modal__head {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 18px 20px 14px; border-bottom: 1px solid var(--pt-stroke);
}
body.ptag-hub .pt-modal__title { margin: 0; font-size: var(--pt-fs-md); color: var(--pt-text-hi); }
body.ptag-hub .pt-modal__close { flex: none; }
body.ptag-hub .pt-modal__close:focus-visible { box-shadow: var(--pt-focus-ring); outline: none; }
body.ptag-hub .pt-modal__search { position: relative; padding: 14px 20px 10px; }
body.ptag-hub .pt-modal__search > .pt-i {
  position: absolute; left: 35px; top: 50%; transform: translateY(calc(-50% + 2px));
  color: var(--pt-text-faint); pointer-events: none;
}
body.ptag-hub .pt-modal__search .pt-input { padding-left: 42px; }
body.ptag-hub .pt-modal__search .pt-input:focus {
  border-color: var(--pt-green); box-shadow: var(--pt-focus-ring); outline: none;
}
body.ptag-hub .pt-modal__list {
  list-style: none; margin: 0; padding: 6px 12px;
  flex: 1 1 auto; min-height: 0; overflow: auto;
}
body.ptag-hub .pt-modal__list li { margin: 0; padding: 0; }
body.ptag-hub .pt-modal__opt {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  width: 100%; text-align: left; cursor: pointer;
  background: none; border: 0; border-radius: var(--pt-r-sm);
  padding: 12px 16px; font-family: var(--pt-font-ui); font-size: var(--pt-fs-base);
  color: var(--pt-text);
  transition: background var(--pt-dur-fast) var(--pt-ease), color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-modal__opt:hover { background: var(--pt-surface-3); color: var(--pt-text-hi); }
body.ptag-hub .pt-modal__opt:focus-visible {
  box-shadow: var(--pt-focus-ring); outline: none;
  background: var(--pt-surface-3); color: var(--pt-text-hi);
}
body.ptag-hub .pt-modal__opt.is-hi { background: var(--pt-surface-3); color: var(--pt-text-hi); }
body.ptag-hub .pt-modal__opt.is-selected { color: var(--pt-text-hi); }
body.ptag-hub .pt-modal__opt-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
body.ptag-hub .pt-modal__opt-check { color: var(--pt-green); flex: none; }
body.ptag-hub.pt-modal-open { overflow: hidden; }
body.ptag-hub .pt-modal__empty { padding: 18px 20px 22px; color: var(--pt-text-mute); font-size: var(--pt-fs-sm); }
body.ptag-hub .pt-modal__foot {
  display: flex; justify-content: flex-end; padding: 12px 20px 16px;
  border-top: 1px solid var(--pt-stroke);
}
@media (prefers-reduced-motion: reduce) {
  body.ptag-hub .pt-modal-backdrop, body.ptag-hub .pt-modal { animation: none; }
}
/* == I5-REFPICKER END == */

/* == I6-STATES START (idea-lifecycle chips + timeline attention; lives inside SKIN:GLOBAL-COMPONENTS) == */
body.ptag-hub .pt-chip[data-state="need_info"]      { color: #fb923c;                       background: rgba(251,146,60,0.1);  border-color: rgba(251,146,60,0.3); }
body.ptag-hub .pt-chip[data-state="in_backlog"]     { color: var(--pt-state-assessed);      background: rgba(56,189,248,0.1);  border-color: rgba(56,189,248,0.3); }
body.ptag-hub .pt-chip[data-state="planned"]        { color: var(--pt-state-in_delivery);   background: rgba(167,139,250,0.1); border-color: rgba(167,139,250,0.3); }
body.ptag-hub .pt-chip[data-state="in_development"] { color: var(--pt-state-approved);      background: rgba(99,223,78,0.1);   border-color: rgba(99,223,78,0.3); }
body.ptag-hub .pt-chip[data-state="unlikely"]       { color: var(--pt-state-declined);      background: rgba(248,113,113,0.1); border-color: rgba(248,113,113,0.3); }
body.ptag-hub .pt-chip[data-state="duplicate"]      { color: var(--pt-state-cancelled);     background: rgba(124,135,152,0.1); border-color: rgba(124,135,152,0.3); }
body.ptag-hub .pt-tl-item.is-attn .pt-tl-node { background: rgba(251,146,60,0.15); border-color: #fb923c; color: #fb923c; }
body.ptag-hub .pt-tl-item.is-attn .pt-tl-title { color: #fb923c; }
/* On Hold (10): paused by PTAG, open, non-terminal side state. fuchsia-100 token + clock icon
   (colour is never the only signal). Mirrors the need_info / is-attn treatment. */
body.ptag-hub .pt-chip[data-state="on_hold"]        { color: var(--pt-state-on_hold, #f5d0fe); background: rgba(245,208,254,0.1); border-color: rgba(245,208,254,0.3); }
body.ptag-hub .pt-tl-item.is-hold .pt-tl-node { background: rgba(245,208,254,0.15); border-color: var(--pt-state-on_hold, #f5d0fe); color: var(--pt-state-on_hold, #f5d0fe); }
body.ptag-hub .pt-tl-item.is-hold .pt-tl-title { color: var(--pt-state-on_hold, #f5d0fe); }
/* == I6-STATES END == */
/* == I10-MOBILE-NAV START (phone nav <=760px; lives inside SKIN:GLOBAL-COMPONENTS;
      the payload hides .pt-nav__links at 760px with no replacement - this is it.
      Desktop-neutral: every base rule is display:none.) == */
body.ptag-hub .pt-nav__burger,
body.ptag-hub .pt-nav__scrim,
body.ptag-hub .pt-nav__mobile { display: none; }
@media (max-width: 760px) {
  body.ptag-hub .pt-nav__inner { position: relative; z-index: 3; }
  body.ptag-hub .pt-nav__inner > .pt-flex { display: none; }
  body.ptag-hub .pt-nav__burger {
    display: inline-flex; flex-direction: column; justify-content: center; align-items: stretch;
    gap: 5px; width: 44px; height: 44px; padding: 0 11px; margin-left: auto;
    background: var(--pt-surface-2); border: 1px solid var(--pt-stroke);
    border-radius: var(--pt-r-sm); cursor: pointer;
  }
  body.ptag-hub .pt-nav__burger-bar {
    display: block; height: 2px; width: 100%; border-radius: 2px;
    background: var(--pt-text-hi);
    transition: transform 0.22s var(--pt-ease), opacity 0.18s var(--pt-ease);
  }
  body.ptag-hub .pt-nav__burger[aria-expanded="true"] .pt-nav__burger-bar:nth-child(1) { transform: translateY(7px) rotate(45deg); }
  body.ptag-hub .pt-nav__burger[aria-expanded="true"] .pt-nav__burger-bar:nth-child(2) { opacity: 0; }
  body.ptag-hub .pt-nav__burger[aria-expanded="true"] .pt-nav__burger-bar:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }
  body.ptag-hub .pt-nav__scrim {
    display: block; position: fixed; top: 0; right: 0; bottom: 0; left: 0; z-index: 1;
    background: rgba(4, 7, 12, 0.6); opacity: 0; pointer-events: none;
    transition: opacity 0.25s var(--pt-ease);
  }
  body.ptag-hub .pt-nav__scrim.is-open { opacity: 1; pointer-events: auto; }
  body.ptag-hub .pt-nav__mobile {
    display: block; position: absolute; top: 100%; left: 0; right: 0; z-index: 2;
    background: var(--pt-bg-1); border-bottom: 1px solid var(--pt-stroke);
    box-shadow: 0 24px 48px rgba(0, 0, 0, 0.45);
    padding: 6px 10px 14px;
    transform: translateY(-10px); opacity: 0; visibility: hidden; pointer-events: none;
    transition: transform 0.26s var(--pt-ease), opacity 0.26s var(--pt-ease), visibility 0s linear 0.26s;
  }
  body.ptag-hub .pt-nav__mobile.is-open {
    transform: none; opacity: 1; visibility: visible; pointer-events: auto; transition-delay: 0s;
  }
  body.ptag-hub .pt-nav__mobile a {
    display: block; padding: 13px 14px; margin-top: 4px;
    color: var(--pt-text); font-size: var(--pt-fs-sm); font-weight: 600;
    border-radius: var(--pt-r-sm);
  }
  body.ptag-hub .pt-nav__mobile a:hover { color: var(--pt-text-hi); background: var(--pt-surface-3); }
  body.ptag-hub .pt-nav__mobile a.is-active { color: var(--pt-green); background: rgba(99, 223, 78, 0.09); }
  body.ptag-hub .pt-nav__mobile-user {
    display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 12px 14px 2px;
    border-top: 1px solid var(--pt-stroke);
    color: var(--pt-text); font-size: var(--pt-fs-sm); font-weight: 600;
  }
  body.ptag-hub.pt-mobilenav-open { overflow: hidden; }
}
/* == I10-MOBILE-NAV END == */

/* == I11-ENGMODAL START (lives inside SKIN:GLOBAL-COMPONENTS) ============ */
/* Clickable engagement row cards (My Engagements) */
body.ptag-hub .pt-rowcard--click {
  cursor: pointer;
  transition: border-color var(--pt-dur-fast) var(--pt-ease),
              transform var(--pt-dur-fast) var(--pt-ease),
              box-shadow var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-rowcard--click:hover { border-color: var(--pt-stroke-strong); transform: translateY(-1px); }
body.ptag-hub .pt-rowcard--click:focus-visible { box-shadow: var(--pt-focus-ring); outline: none; }
body.ptag-hub .pt-rowcard__go { color: var(--pt-text-faint); flex: none; }
body.ptag-hub .pt-rowcard--click:hover .pt-rowcard__go { color: var(--pt-green); }

/* Engagement detail modal - variant of the i5 .pt-modal system */
body.ptag-hub .pt-modal--eng { max-width: 680px; max-height: 86vh; }
body.ptag-hub .pt-modal__body { padding: 18px 20px 20px; overflow: auto; }
body.ptag-hub .pt-dm__top { display: flex; align-items: flex-start; justify-content: space-between; gap: 14px; }
body.ptag-hub .pt-dm__t { margin: 0; font-size: var(--pt-fs-md); color: var(--pt-text-hi); line-height: 1.4; }
body.ptag-hub .pt-dm__top .pt-chip { flex: none; margin-top: 2px; }
body.ptag-hub .pt-dm__ctx { margin: 8px 0 0; color: var(--pt-text-mute); font-size: var(--pt-fs-sm); }
body.ptag-hub .pt-dm__meta {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px;
  margin: 16px 0 2px; padding: 13px 0;
  border-top: 1px solid var(--pt-stroke); border-bottom: 1px solid var(--pt-stroke);
}
body.ptag-hub .pt-dm__k {
  font-size: var(--pt-fs-xs); color: var(--pt-text-faint);
  text-transform: uppercase; letter-spacing: 0.07em; margin-bottom: 3px;
}
body.ptag-hub .pt-dm__v { font-size: var(--pt-fs-sm); color: var(--pt-text); font-weight: 600; overflow-wrap: anywhere; }
body.ptag-hub .pt-dm__sec {
  margin: 18px 0 10px; font-size: var(--pt-fs-xs); font-weight: 700;
  color: var(--pt-text-mute); text-transform: uppercase; letter-spacing: 0.09em;
}

/* Comment thread - customer-visible journal */
body.ptag-hub .pt-thread {
  list-style: none; margin: 0; padding: 0;
  max-height: 300px; overflow: auto;
  display: flex; flex-direction: column; gap: 10px;
}
body.ptag-hub .pt-thread__item {
  background: var(--pt-surface-2); border: 1px solid var(--pt-stroke);
  border-radius: var(--pt-r-md); padding: 10px 14px;
}
body.ptag-hub .pt-thread__item.is-mine { border-left: 2px solid var(--pt-green); }
body.ptag-hub .pt-thread__meta {
  display: flex; align-items: baseline; justify-content: space-between;
  gap: 10px; margin-bottom: 4px; flex-wrap: wrap;
}
body.ptag-hub .pt-thread__who { color: var(--pt-text-hi); font-weight: 600; font-size: var(--pt-fs-sm); }
body.ptag-hub .pt-thread__when { color: var(--pt-text-faint); font-size: var(--pt-fs-xs); }
body.ptag-hub .pt-thread__text {
  color: var(--pt-text); font-size: var(--pt-fs-sm); line-height: 1.55;
  white-space: pre-wrap; overflow-wrap: anywhere;
}
body.ptag-hub .pt-thread__empty { color: var(--pt-text-mute); font-size: var(--pt-fs-sm); padding: 10px 2px 2px; }

/* Composer */
body.ptag-hub .pt-composer { margin-top: 12px; }
body.ptag-hub .pt-composer .pt-textarea { display: block; width: 100%; }
body.ptag-hub .pt-composer__row {
  display: flex; align-items: center; justify-content: flex-end;
  gap: 12px; margin-top: 10px; flex-wrap: wrap;
}

/* Mobile (390px class of devices) */
@media (max-width: 640px) {
  body.ptag-hub .pt-modal-backdrop { padding: 4vh 10px 10px; }
  body.ptag-hub .pt-modal--eng { max-height: 92vh; }
  body.ptag-hub .pt-dm__top { flex-direction: column; gap: 8px; }
  body.ptag-hub .pt-dm__meta { grid-template-columns: 1fr 1fr; }
  body.ptag-hub .pt-thread { max-height: 240px; }
}
/* == I11-ENGMODAL END == */

/* == I12-PIPE-LINKS START (lives inside SKIN:GLOBAL-COMPONENTS) ========== */
/* Landing pipeline rows are real anchors now (?id=ptag_status&state=<slug>):
   two-line items - chip + count/go icon, then the I6 state-context sub-note.
   Hover/focus affordance mirrors .pt-rowcard--click (lift + border glow). */
body.ptag-hub .pt-pipe__row {
  display: block; padding: 9px 10px; margin: 0 -10px;
  border-radius: 10px;
  text-decoration: none; color: inherit; cursor: pointer;
  transition: background-color var(--pt-dur-fast) var(--pt-ease),
              box-shadow var(--pt-dur-fast) var(--pt-ease),
              transform var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-pipe__row:hover {
  background: rgba(255,255,255,.04);
  box-shadow: inset 0 0 0 1px var(--pt-stroke-strong);
  transform: translateY(-1px);
}
body.ptag-hub .pt-pipe__row:focus-visible { outline: none; box-shadow: var(--pt-focus-ring); }
body.ptag-hub .pt-pipe__main { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
body.ptag-hub .pt-pipe__right { display: flex; align-items: center; gap: 8px; }
body.ptag-hub .pt-pipe__go {
  color: var(--pt-text); opacity: .35;
  transition: opacity var(--pt-dur-fast) var(--pt-ease), color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-pipe__row:hover .pt-pipe__go,
body.ptag-hub .pt-pipe__row:focus-visible .pt-pipe__go { opacity: 1; color: var(--pt-green); }
body.ptag-hub .pt-pipe__note {
  margin-top: 4px; font-size: var(--pt-fs-sm); color: var(--pt-text);
  opacity: .62; line-height: 1.45;
}

/* My Engagements state filter bar (?state=<slug>, whitelisted server-side) */
body.ptag-hub .pt-filterbar {
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  margin-bottom: 18px; padding: 10px 14px;
  border: 1px solid var(--pt-stroke); border-radius: 12px;
  background: rgba(255,255,255,.03);
}
body.ptag-hub .pt-filterbar__label { font-size: var(--pt-fs-sm); color: var(--pt-text); opacity: .75; }
body.ptag-hub .pt-filterbar__n {
  font-family: var(--pt-font-display); font-weight: 700;
  color: var(--pt-text-hi); font-variant-numeric: tabular-nums;
}
body.ptag-hub .pt-filterbar__all { margin-left: auto; }
/* == I12-PIPE-LINKS END == */

/* == I13-SCROLLNAV+FILTERS START (lives inside SKIN:GLOBAL-COMPONENTS; I14 dropped the R5b hover accordion) === */
/* smooth-scroll targets clear the fixed nav */
body.ptag-hub [id^="pt-sec-"] { scroll-margin-top: calc(var(--pt-nav-h) + 12px); }

/* ---- R1a: landing section dot-rail (fixed right gutter) ---- */
body.ptag-hub .pt-dotrail {
  position: fixed; top: 50%; right: 18px; transform: translateY(-50%);
  z-index: 40; display: none; pointer-events: none;
}
body.ptag-hub .pt-dotrail__list {
  list-style: none; margin: 0; padding: 0;
  display: flex; flex-direction: column; gap: 14px; align-items: flex-end;
}
body.ptag-hub .pt-dotrail__item { display: block; }
body.ptag-hub .pt-dotrail__dot {
  pointer-events: auto; position: relative;
  display: flex; align-items: center; justify-content: flex-end;
  width: 22px; height: 22px; padding: 0; margin: 0;
  background: transparent; border: 0; cursor: pointer; -webkit-appearance: none; appearance: none;
}
body.ptag-hub .pt-dotrail__dot::after {
  content: ""; width: 9px; height: 9px; border-radius: var(--pt-r-full);
  background: var(--pt-stroke-strong); box-shadow: 0 0 0 4px transparent;
  transition: background-color var(--pt-dur-fast) var(--pt-ease),
              box-shadow var(--pt-dur-fast) var(--pt-ease),
              transform var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-dotrail__dot:hover::after { background: var(--pt-text-mute); transform: scale(1.15); }
body.ptag-hub .pt-dotrail__dot.is-active::after {
  background: var(--pt-green); transform: scale(1.2); box-shadow: 0 0 0 4px rgba(99, 223, 78, 0.14);
}
body.ptag-hub .pt-dotrail__dot:focus-visible { outline: none; }
body.ptag-hub .pt-dotrail__dot:focus-visible::after { box-shadow: var(--pt-focus-ring); }
body.ptag-hub .pt-dotrail__label {
  position: absolute; right: 28px; top: 50%; transform: translateY(-50%) translateX(6px);
  white-space: nowrap; padding: 4px 10px; border-radius: var(--pt-r-sm);
  font-family: var(--pt-font-ui); font-size: var(--pt-fs-xs); font-weight: 600;
  color: var(--pt-text-hi); background: var(--pt-surface-2);
  border: 1px solid var(--pt-stroke); box-shadow: var(--pt-shadow-2);
  opacity: 0; pointer-events: none;
  transition: opacity var(--pt-dur-fast) var(--pt-ease), transform var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-dotrail__dot:hover .pt-dotrail__label,
body.ptag-hub .pt-dotrail__dot:focus-visible .pt-dotrail__label { opacity: 1; transform: translateY(-50%) translateX(0); }
/* Only where a non-overlapping outer gutter actually exists for the 1200px shell
   (>=1280px -> >=40px gutter). Below that the margin is too tight -> stays hidden. */
@media (min-width: 1280px) { body.ptag-hub .pt-dotrail { display: block; } }

/* ---- R1b: hero scroll cue ---- */
body.ptag-hub .pt-scrollcue {
  position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%);
  z-index: 30; display: inline-flex; flex-direction: column; align-items: center; gap: 4px;
  padding: 6px 10px; background: transparent; border: 0; cursor: pointer;
  color: var(--pt-text-mute); font-family: var(--pt-font-ui);
  font-size: var(--pt-fs-xs); font-weight: 600; letter-spacing: .06em; text-transform: uppercase;
  opacity: .8; transition: opacity var(--pt-dur) var(--pt-ease), transform var(--pt-dur) var(--pt-ease);
}
body.ptag-hub .pt-scrollcue:hover { opacity: 1; color: var(--pt-text); }
body.ptag-hub .pt-scrollcue:focus-visible { outline: none; box-shadow: var(--pt-focus-ring); border-radius: var(--pt-r-sm); }
body.ptag-hub .pt-scrollcue__chev { animation: pt-cue-float 1.8s var(--pt-ease) infinite; }
body.ptag-hub .pt-scrollcue.is-hidden { opacity: 0; transform: translateX(-50%) translateY(8px); pointer-events: none; }
@keyframes pt-cue-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(4px); } }
@media (max-width: 760px) { body.ptag-hub .pt-scrollcue { display: none; } }

/* ---- R2: landing track-by-number row (inside the glass card) ---- */
body.ptag-hub .pt-tracknum { margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--pt-stroke); }
body.ptag-hub .pt-tracknum__form { display: flex; gap: 8px; align-items: stretch; }
body.ptag-hub .pt-tracknum__input { flex: 1; margin: 0; }
body.ptag-hub .pt-tracknum__go { flex: 0 0 auto; white-space: nowrap; }
body.ptag-hub .pt-tracknum__help { margin: 8px 0 0; font-size: var(--pt-fs-xs); color: var(--pt-text-mute); line-height: 1.4; }
body.ptag-hub .pt-tracknum__help.is-err { color: var(--pt-state-declined); }
body.ptag-hub .pt-tracknum__form.is-invalid .pt-tracknum__input { border-color: var(--pt-state-declined); animation: pt-shake .4s var(--pt-ease); }

/* ---- R4: My Engagements static filter bar ---- */
body.ptag-hub .pt-filterbar--static { justify-content: space-between; gap: 12px 16px; }
body.ptag-hub .pt-chipset { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
body.ptag-hub .pt-fchip {
  display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px;
  border-radius: var(--pt-r-full); border: 1px solid var(--pt-stroke); background: rgba(255, 255, 255, .03);
  color: var(--pt-text); font-family: var(--pt-font-ui); font-size: var(--pt-fs-sm);
  cursor: pointer; -webkit-appearance: none; appearance: none;
  transition: border-color var(--pt-dur-fast) var(--pt-ease),
              background-color var(--pt-dur-fast) var(--pt-ease),
              color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-fchip:hover { border-color: var(--pt-stroke-strong); color: var(--pt-text-hi); }
body.ptag-hub .pt-fchip:focus-visible { outline: none; box-shadow: var(--pt-focus-ring); }
body.ptag-hub .pt-fchip__n {
  font-family: var(--pt-font-display); font-weight: 700; font-variant-numeric: tabular-nums;
  font-size: var(--pt-fs-xs); color: var(--pt-text-mute); min-width: 16px; text-align: center;
}
body.ptag-hub .pt-fchip.is-active { border-color: var(--pt-stroke-brand); background: rgba(99, 223, 78, 0.12); color: var(--pt-text-hi); }
body.ptag-hub .pt-fchip.is-active .pt-fchip__n { color: var(--pt-green); }
body.ptag-hub .pt-numfilter {
  display: flex; align-items: center; gap: 4px; position: relative;
  padding: 3px 6px 3px 10px; border-radius: var(--pt-r-full);
  border: 1px solid var(--pt-stroke); background: var(--pt-surface-1);
}
body.ptag-hub .pt-numfilter__icon { color: var(--pt-text-faint); flex: 0 0 auto; }
body.ptag-hub .pt-numfilter__input {
  border: 0; background: transparent; outline: none;
  color: var(--pt-text-hi); font-family: var(--pt-font-ui); font-size: var(--pt-fs-sm);
  width: 130px; padding: 4px 2px;
}
body.ptag-hub .pt-numfilter__input::placeholder { color: var(--pt-text-faint); }
body.ptag-hub .pt-numfilter__go, body.ptag-hub .pt-numfilter__clear {
  flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; border-radius: var(--pt-r-full); border: 0; background: transparent;
  color: var(--pt-text-mute); cursor: pointer;
  transition: background-color var(--pt-dur-fast) var(--pt-ease), color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-numfilter__go:hover, body.ptag-hub .pt-numfilter__clear:hover { background: rgba(255, 255, 255, .06); color: var(--pt-text-hi); }
body.ptag-hub .pt-numfilter__go:focus-visible, body.ptag-hub .pt-numfilter__clear:focus-visible { outline: none; box-shadow: var(--pt-focus-ring); }
body.ptag-hub .pt-numfilter.is-invalid { border-color: var(--pt-state-declined); animation: pt-shake .4s var(--pt-ease); }
@media (max-width: 620px) {
  body.ptag-hub .pt-filterbar--static { flex-direction: column; align-items: stretch; }
  body.ptag-hub .pt-numfilter__input { width: 100%; }
}

/* ---- R5a: modal journey section + compact timeline (base pt-tl classes already global) ---- */
body.ptag-hub .pt-dm__timeline { margin: 4px 0 8px; }
body.ptag-hub .pt-timeline--compact .pt-tl-item { gap: 10px; padding-bottom: 12px; }
body.ptag-hub .pt-timeline--compact .pt-tl-node { width: 26px; height: 26px; }
body.ptag-hub .pt-timeline--compact .pt-tl-title { font-size: var(--pt-fs-sm); }
body.ptag-hub .pt-timeline--compact .pt-tl-sub { font-size: var(--pt-fs-xs); }

/* ---- shared: reduced-motion off-switch for the I13 animations ---- */
@media (prefers-reduced-motion: reduce) {
  body.ptag-hub .pt-scrollcue__chev { animation: none; }
  body.ptag-hub .pt-tracknum__form.is-invalid .pt-tracknum__input { animation: none; }
  body.ptag-hub .pt-numfilter.is-invalid { animation: none; }
}
@keyframes pt-shake {
  10%, 90% { transform: translateX(-1px); } 20%, 80% { transform: translateX(2px); }
  30%, 50%, 70% { transform: translateX(-4px); } 40%, 60% { transform: translateX(4px); }
}
/* == I13-SCROLLNAV+FILTERS END == */

/* == I14-PAGER START (My Engagements adaptive pagination; tokens only) === */
body.ptag-hub .pt-pager {
  display: flex; align-items: center; justify-content: space-between; gap: 12px 16px;
  flex-wrap: wrap; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--pt-stroke);
}
body.ptag-hub .pt-pager__size { display: flex; align-items: center; gap: 8px; }
body.ptag-hub .pt-pager__lbl { font-size: var(--pt-fs-sm); color: var(--pt-text-mute); }
body.ptag-hub .pt-pager__selwrap { position: relative; display: inline-flex; align-items: center; }
body.ptag-hub .pt-pager__select {
  -webkit-appearance: none; appearance: none; cursor: pointer;
  background: var(--pt-surface-2); color: var(--pt-text-hi);
  border: 1px solid var(--pt-stroke); border-radius: var(--pt-r-sm);
  padding: 6px 30px 6px 12px; font-family: var(--pt-font-ui); font-size: var(--pt-fs-sm);
  font-variant-numeric: tabular-nums;
  transition: border-color var(--pt-dur-fast) var(--pt-ease), box-shadow var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-pager__select:hover { border-color: var(--pt-stroke-strong); }
body.ptag-hub .pt-pager__select:focus, body.ptag-hub .pt-pager__select:focus-visible {
  border-color: var(--pt-green); box-shadow: var(--pt-focus-ring); outline: none;
}
body.ptag-hub .pt-pager__select option { background: var(--pt-surface-2); color: var(--pt-text-hi); }
body.ptag-hub .pt-pager__chev {
  position: absolute; right: 10px; top: 50%; transform: translateY(-50%);
  color: var(--pt-text-mute); pointer-events: none;
}
body.ptag-hub .pt-pager__nav { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
body.ptag-hub .pt-pager__range { font-size: var(--pt-fs-sm); color: var(--pt-text); font-variant-numeric: tabular-nums; }
body.ptag-hub .pt-pager__btns { display: inline-flex; align-items: center; gap: 8px; }
body.ptag-hub .pt-pager__pos { font-size: var(--pt-fs-xs); color: var(--pt-text-mute); font-variant-numeric: tabular-nums; min-width: 84px; text-align: center; }
body.ptag-hub .pt-pager__btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 34px; height: 34px; padding: 0; border-radius: var(--pt-r-sm);
  background: var(--pt-surface-2); border: 1px solid var(--pt-stroke);
  color: var(--pt-text-mute); cursor: pointer;
  transition: border-color var(--pt-dur-fast) var(--pt-ease), color var(--pt-dur-fast) var(--pt-ease), background var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-pager__btn:hover:not(:disabled) { border-color: var(--pt-stroke-strong); color: var(--pt-text-hi); background: var(--pt-surface-3); }
body.ptag-hub .pt-pager__btn:focus-visible { outline: none; box-shadow: var(--pt-focus-ring); }
body.ptag-hub .pt-pager__btn:disabled { opacity: .4; cursor: default; }
body.ptag-hub .pt-pager__btn--prev svg { transform: scaleX(-1); }
@media (max-width: 620px) {
  body.ptag-hub .pt-pager { flex-direction: column; align-items: stretch; gap: 12px; }
  body.ptag-hub .pt-pager__nav { justify-content: space-between; }
}
/* == I14-PAGER END == */

/* == I14-HEADER-LOGOS START (Jon: brand logos ~37% taller. Base
   .pt-nav__brand svg is height:24px in the design-system LINK payload
   (untouched); these higher-specificity rules override it. Nav height stays
   var(--pt-nav-h)=68px -> no nav-height jump; logos vertically centered;
   divider + gap rescaled to match. Tokens only, no new hex.) === */
body.ptag-hub .pt-nav .pt-nav__brand svg,
body.ptag-hub .pt-nav .pt-nav__brand img { height: 40px; }  /* I25: Jon asked for a little bigger; 40px in a 68px nav */
body.ptag-hub .pt-nav .pt-nav__brand { gap: 18px; }
body.ptag-hub .pt-nav .pt-nav__divider { height: 30px; }
/* == I14-HEADER-LOGOS END == */

/* == I16-EXPLORE START (Jon: two STATIC rectangular controls with UPRIGHT
   letters. The column stays vertical via writing-mode, but text-orientation is
   'upright' rather than 'mixed', so each letter stands up instead of lying on
   its side. Upright stacking needs almost no letter-spacing, hence .02em.
   Geometry derived from measured values: the dot-rail is 130px tall
   (4 x 22px dots + 3 x 14px gaps) centred at 50%, and the
   upright label is 7 x 12px, giving a ~132px button. Gates: the width
   gate matches .pt-dotrail exactly (min-width 1280px) so the controls come and go
   WITH the dots, plus a min-height gate so they stand down in a window too short
   for them and the rail to coexist. Tokens only, no new colour values.) == */
body.ptag-hub .pt-scrollcue {
  display: none;                      /* gated below, in lockstep with .pt-dotrail */
  left: auto; right: 18px; top: auto; bottom: auto;
  flex-direction: column; align-items: center; gap: 8px;
  padding: 11px 8px;
  border-radius: var(--pt-r-sm, 6px);
  background: var(--pt-glass);
  border: 1px solid var(--pt-stroke);
  box-shadow: var(--pt-shadow-2);
  -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
  transform: none;
  opacity: 0; pointer-events: none;
  transition: opacity .28s var(--pt-ease), transform .28s var(--pt-ease),
              color var(--pt-dur) var(--pt-ease);
}
@media (min-width: 1280px) and (min-height: 640px) {
  body.ptag-hub .pt-scrollcue { display: inline-flex; }
}
body.ptag-hub .pt-scrollcue.is-on { opacity: .9; pointer-events: auto; }
body.ptag-hub .pt-scrollcue.is-on:hover { opacity: 1; }
body.ptag-hub .pt-scrollcue--up { top: 88px; transform: translateY(-6px); }
body.ptag-hub .pt-scrollcue--up.is-on { transform: translateY(0); }
body.ptag-hub .pt-scrollcue--down { bottom: 28px; transform: translateY(6px); }
body.ptag-hub .pt-scrollcue--down.is-on { transform: translateY(0); }
body.ptag-hub .pt-scrollcue__t {
  writing-mode: vertical-rl;
  font-size: 11px;
  text-orientation: upright;          /* letters stand up, not on their side */
  -webkit-text-orientation: upright;
  letter-spacing: .02em; line-height: 1;
}
body.ptag-hub .pt-scrollcue__chevwrap { display: inline-flex; }
body.ptag-hub .pt-scrollcue--up .pt-scrollcue__chevwrap { transform: rotate(180deg); }
@media (prefers-reduced-motion: reduce) {
  body.ptag-hub .pt-scrollcue { transition: opacity .01s; }
}
/* == I16-EXPLORE END == */

/* == I17-PULSE-FLASH START (Jon: (a) every journey step pulses, not just the
   current one. pt-pulse hard-codes green, so the colour moves to a per-state
   custom property and the ring reads var(--pt-pulse-c); steps stagger so the
   timeline ripples instead of blinking in unison. (b) the filter flash: the list
   wrapper used to be removed from the DOM on every refilter, which both swapped
   in the skeleton AND replayed the .pt-reveal entrance animation. It now stays
   mounted and simply dims. Tokens and existing state colours only.) == */
body.ptag-hub .pt-tl-item .pt-tl-node {
  --pt-pulse-c: rgba(99, 223, 78, .40);
  animation: pt-pulse-any 2.2s var(--pt-ease) infinite;
}
body.ptag-hub .pt-tl-item.is-attn .pt-tl-node { --pt-pulse-c: rgba(251, 146, 60, .42); }
body.ptag-hub .pt-tl-item.is-negative .pt-tl-node { --pt-pulse-c: rgba(248, 113, 113, .42); }
body.ptag-hub .pt-tl-item.is-hold .pt-tl-node { --pt-pulse-c: rgba(245, 208, 254, .42); }
body.ptag-hub .pt-tl-item.is-future .pt-tl-node { --pt-pulse-c: rgba(148, 163, 184, .30); }
body.ptag-hub .pt-tl-item:nth-child(2) .pt-tl-node { animation-delay: .16s; }
body.ptag-hub .pt-tl-item:nth-child(3) .pt-tl-node { animation-delay: .32s; }
body.ptag-hub .pt-tl-item:nth-child(4) .pt-tl-node { animation-delay: .48s; }
body.ptag-hub .pt-tl-item:nth-child(5) .pt-tl-node { animation-delay: .64s; }
body.ptag-hub .pt-tl-item:nth-child(6) .pt-tl-node { animation-delay: .80s; }
body.ptag-hub .pt-tl-item:nth-child(7) .pt-tl-node { animation-delay: .96s; }
body.ptag-hub .pt-tl-item:nth-child(8) .pt-tl-node { animation-delay: 1.12s; }
@keyframes pt-pulse-any {
  0%   { box-shadow: 0 0 0 0 var(--pt-pulse-c); }
  70%  { box-shadow: 0 0 0 12px rgba(0, 0, 0, 0); }
  100% { box-shadow: 0 0 0 0 rgba(0, 0, 0, 0); }
}
/* refilter: keep the list, just soften it. No unmount, so no entrance replay. */
body.ptag-hub .pt-reveal.is-refetching {
  opacity: .55; pointer-events: none; transition: opacity .16s var(--pt-ease);
}
@media (prefers-reduced-motion: reduce) {
  body.ptag-hub .pt-tl-item .pt-tl-node { animation: none; }
}
/* == I17-PULSE-FLASH END == */

/* == I19-SINGLE-SCROLL START (Jon: the drill-in modal had TWO nested scrollers,
   .pt-modal__body and .pt-thread, so the wheel behaved differently depending on
   where the pointer sat and handed off mid-gesture at the end of the inner list.
   The thread stops being a scroll container; the modal body is the single
   surface. Purely behavioural: no card, spacing, border or colour changes.
   overscroll-behavior stops a gesture bleeding through to the page behind, and
   scroll-behavior makes the post-comment jump glide rather than snap. Note
   scroll-behavior only affects PROGRAMMATIC scrolling, so the wheel stays
   immediate.) == */
body.ptag-hub .pt-thread { max-height: none; overflow: visible; }
body.ptag-hub .pt-modal--eng .pt-modal__body {
  overscroll-behavior: contain;
  scroll-behavior: smooth;
}
@media (prefers-reduced-motion: reduce) {
  body.ptag-hub .pt-modal--eng .pt-modal__body { scroll-behavior: auto; }
}
/* == I19-SINGLE-SCROLL END == */

/* == I20-UNREAD START (Jon: "if there is an additional comment that is not from
   the person whose engagements these are ... some sort of an icon that glows or
   pulsates gently on just the record that hasn't been drilled into or unlocked
   yet". He described two states, so there are two:
     .pt-unread           someone else spoke last and you still owe a reply ->
                          quiet, neutral, static. Reading does not clear it.
     .pt-unread.is-live   ...and you have not opened it since -> pulses.
   Reuses the I17 pt-pulse-any ring and existing tokens, so nothing already on
   the row card moves or changes colour. Rows stagger, so a page of them ripples
   instead of blinking in unison. == */
body.ptag-hub .pt-unread {
  display: inline-flex; align-items: center; gap: 5px; flex: none;
  padding: 3px 8px; border-radius: var(--pt-r-sm);
  font-size: 11px; font-weight: 600; line-height: 1;
  color: var(--pt-text-mute);
  background: rgba(148, 163, 184, .10);
  border: 1px solid rgba(148, 163, 184, .24);
  transition: color var(--pt-dur-fast) var(--pt-ease),
              background var(--pt-dur-fast) var(--pt-ease),
              border-color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-unread .pt-i { width: 13px; height: 13px; flex: none; }
body.ptag-hub .pt-unread.is-live {
  color: var(--pt-green);
  background: rgba(99, 223, 78, .12);
  border-color: rgba(99, 223, 78, .32);
  --pt-pulse-c: rgba(99, 223, 78, .34);
  animation: pt-pulse-any 2.8s var(--pt-ease) infinite;
}
body.ptag-hub .pt-rowcard:nth-child(2) .pt-unread.is-live { animation-delay: .20s; }
body.ptag-hub .pt-rowcard:nth-child(3) .pt-unread.is-live { animation-delay: .40s; }
body.ptag-hub .pt-rowcard:nth-child(4) .pt-unread.is-live { animation-delay: .60s; }
body.ptag-hub .pt-rowcard:nth-child(5) .pt-unread.is-live { animation-delay: .80s; }
body.ptag-hub .pt-rowcard:nth-child(6) .pt-unread.is-live { animation-delay: 1.00s; }
body.ptag-hub .pt-rowcard:nth-child(7) .pt-unread.is-live { animation-delay: 1.20s; }
@media (prefers-reduced-motion: reduce) {
  body.ptag-hub .pt-unread.is-live { animation: none; }
}
/* == I20-UNREAD END == */

/* == I21-SIGNAL START (Jon: "at the top of the portal, if I have any additional
   comments that need to be addressed ... use the same icon ... make it pulsate,
   and have it have the aggregate count". Same green, same pt-pulse-any ring and
   same glyph as the row badge, so the nav indicator and the list read as one
   system. Sized up slightly because it sits in the nav bar rather than a row.) == */
body.ptag-hub .pt-signal {
  display: inline-flex; align-items: center; gap: 6px; flex: none;
  padding: 5px 10px; border-radius: var(--pt-r-sm);
  font-size: 12px; font-weight: 700; line-height: 1; text-decoration: none;
  color: var(--pt-green);
  background: rgba(99, 223, 78, .12);
  border: 1px solid rgba(99, 223, 78, .32);
  --pt-pulse-c: rgba(99, 223, 78, .34);
  animation: pt-pulse-any 2.8s var(--pt-ease) infinite;
  transition: background var(--pt-dur-fast) var(--pt-ease),
              border-color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-signal:hover {
  background: rgba(99, 223, 78, .20); border-color: rgba(99, 223, 78, .52);
}
body.ptag-hub .pt-signal:focus-visible { box-shadow: var(--pt-focus-ring); outline: none; }
body.ptag-hub .pt-signal .pt-i { width: 14px; height: 14px; flex: none; }
body.ptag-hub .pt-nav__mobile .pt-signal__n {
  margin-left: 8px; padding: 2px 8px; border-radius: 999px;
  background: rgba(99, 223, 78, .16); color: var(--pt-green); font-weight: 700;
}
/* the awaiting chip in the filter bar carries the same glyph */
body.ptag-hub .pt-fchip__i { width: 13px; height: 13px; margin-right: 5px; vertical-align: -2px; }
@media (prefers-reduced-motion: reduce) {
  body.ptag-hub .pt-signal { animation: none; }
}
/* == I21-SIGNAL END == */

/* == I22-BOOT-CHROME START ================================================
   (a) FIRST PAINT. The design system is injected at runtime by ptag_global's
   link function, so before Angular boots the document has no styling at all -
   that is the OOB white page with the spinner Jon called out. Everything in
   this first group ships in the widget css field, which Service Portal compiles
   into <head>, so it paints before a single script runs.
   The splash clears the moment the app marks the body .ptag-hub, and there is a
   hard 8s timeout fallback so a failed boot can never leave it stuck on screen.
   (b) The profile menu, which did not exist: there was no way to sign out.
   (c) Hero spacing. The hero opened 172px down (68px nav + 104px padding), which
   pushed the glass panel - and the PTAG-number lookup at the bottom of it -
   under the fold on a laptop. Tightened, and tightened further as the viewport
   gets shorter. Selectors carry one extra element to outrank the injected
   rules whichever stylesheet lands last. == */

/* ---------- (a) first paint + splash: MOVED TO THE THEME ----------
   Widget css is delivered after Angular boots, so a pre-boot splash here
   was a contradiction. It now lives in sp_theme.css_variables, which is
   compiled into sp-bootstrap-rem.scss and linked in <head>. Verified by
   fetching all six shell stylesheets: the marker was in none of them.
   ---------- */

/* ---------- (b) profile menu ---------- */
body.ptag-hub .pt-usermenu { position: relative; flex: none; }
body.ptag-hub .pt-usermenu__btn {
  display: inline-flex; align-items: center; gap: 8px;
  background: transparent; border: 1px solid transparent; cursor: pointer;
  padding: 4px 8px 4px 4px; border-radius: 999px; font: inherit;
  color: var(--pt-text-hi);
  transition: background var(--pt-dur-fast) var(--pt-ease),
              border-color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-usermenu__btn:hover {
  background: rgba(255, 255, 255, .05); border-color: var(--pt-stroke-strong);
}
body.ptag-hub .pt-usermenu__btn:focus-visible { box-shadow: var(--pt-focus-ring); outline: none; }
body.ptag-hub .pt-usermenu__chev {
  width: 13px; height: 13px; color: var(--pt-text-faint);
  transition: transform var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-usermenu.is-open .pt-usermenu__chev { transform: rotate(180deg); }
body.ptag-hub .pt-usermenu__pop {
  position: absolute; top: calc(100% + 10px); right: 0; z-index: 90;
  min-width: 252px; padding: 6px;
  background: var(--pt-bg-1); border: 1px solid var(--pt-stroke-strong);
  border-radius: 12px; box-shadow: 0 18px 44px rgba(0, 0, 0, .5);
  opacity: 0; visibility: hidden; transform: translateY(-6px);
  transition: opacity var(--pt-dur-fast) var(--pt-ease),
              transform var(--pt-dur-fast) var(--pt-ease),
              visibility 0s linear var(--pt-dur-fast);
}
body.ptag-hub .pt-usermenu__pop.is-open {
  opacity: 1; visibility: visible; transform: translateY(0);
  transition-delay: 0s;
}
body.ptag-hub .pt-usermenu__head {
  display: flex; align-items: center; gap: 11px;
  padding: 11px 12px 13px; border-bottom: 1px solid var(--pt-stroke); margin-bottom: 6px;
}
body.ptag-hub .pt-usermenu__full {
  font-size: 13px; font-weight: 600; color: var(--pt-text-hi); line-height: 1.3;
}
body.ptag-hub .pt-usermenu__mail {
  font-size: 11.5px; color: var(--pt-text-mute); margin-top: 2px;
  word-break: break-all; line-height: 1.35;
}
body.ptag-hub .pt-usermenu__item {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 12px; border-radius: 8px; text-decoration: none;
  font-size: 13px; color: var(--pt-text-mute);
  transition: background var(--pt-dur-fast) var(--pt-ease), color var(--pt-dur-fast) var(--pt-ease);
}
body.ptag-hub .pt-usermenu__item:hover { background: rgba(255, 255, 255, .05); color: var(--pt-text-hi); }
body.ptag-hub .pt-usermenu__item:focus-visible { box-shadow: var(--pt-focus-ring); outline: none; }
body.ptag-hub .pt-usermenu__item--out:hover { color: #fca5a5; }
body.ptag-hub .pt-usermenu__sep { height: 1px; background: var(--pt-stroke); margin: 6px 4px; }

/* ---------- (c) hero fits the fold ---------- */
body.ptag-hub section.pt-hero { padding: var(--pt-sp-9) 0 var(--pt-sp-10); }
body.ptag-hub .pt-hero .pt-hero__title { margin: var(--pt-sp-4) 0; }
@media (max-height: 900px) {
  body.ptag-hub section.pt-hero { padding: 34px 0 44px; }
  body.ptag-hub .pt-hero .pt-hero__grid { gap: var(--pt-sp-8); align-items: start; }
  body.ptag-hub .pt-hero .pt-hero__title { margin: 12px 0; }
}
@media (max-height: 780px) {
  body.ptag-hub section.pt-hero { padding: 22px 0 32px; }
  body.ptag-hub .pt-hero .pt-hero__sub { margin-bottom: 14px; }
  body.ptag-hub .pt-hero .pt-hero__note { display: none; }
}
/* the number lookup is the thing Jon could not find - give it a little presence */
body.ptag-hub .pt-tracknum { margin-top: 16px; padding-top: 14px; }
/* == I22-BOOT-CHROME END == */

/* == I29-NEW-COMMENT START (Jon: "an indicator that shows which one of the
   comments are new ... subtle ... within taste of the theme".) A small chip in
   the meta row plus a hairline green edge on the entry, so the thread is
   scannable without anything shouting. Deliberately STATIC: no ring, no pulse.
   "New" here means the same thing the row badge counts - posted by somebody else
   since your own last reply - so two on the badge is always two chips here. == */
body.ptag-hub .pt-thread__new {
  display: inline-flex; align-items: center; flex: none;
  padding: 2px 7px; border-radius: 999px;
  font-size: 9.5px; font-weight: 700; line-height: 1;
  letter-spacing: .08em; text-transform: uppercase;
  color: var(--pt-green);
  background: rgba(99, 223, 78, .11);
  border: 1px solid rgba(99, 223, 78, .26);
}
body.ptag-hub .pt-thread__item.is-new {
  /* NOT a left edge: .is-mine already owns that cue (border-left green), and
     reusing it here would make "somebody else replied" look like "this one is
     mine". A faint field instead, which groups several new entries visually
     without borrowing the other state's language. */
  background: rgba(99, 223, 78, .045);
  border-color: rgba(99, 223, 78, .20);
}
/* == I29-NEW-COMMENT END == */

/* == I30-ATTACHMENTS START (Jon: "we need to allow for attachments as well from
   the customer or whoever the audience is of this portal".) Same surface, border
   and radius language as the comment entries so the two sections read as one
   conversation rather than two systems. Static, no motion. == */
body.ptag-hub .pt-files__input { position: absolute; width: 1px; height: 1px; opacity: 0; pointer-events: none; }
body.ptag-hub .pt-files { list-style: none; margin: 0 0 10px; padding: 0; display: flex; flex-direction: column; gap: 8px; }
body.ptag-hub .pt-files__item {
  display: flex; align-items: center; gap: 10px;
  background: var(--pt-surface-2); border: 1px solid var(--pt-stroke);
  border-radius: var(--pt-r-md); padding: 8px 10px 8px 12px;
}
body.ptag-hub .pt-files__ico { color: var(--pt-text-faint); flex: none; }
body.ptag-hub .pt-files__name {
  color: var(--pt-text-hi); font-size: var(--pt-fs-sm); font-weight: 600;
  text-decoration: none; overflow-wrap: anywhere; flex: 1 1 auto;
}
body.ptag-hub .pt-files__name:hover { color: var(--pt-green); text-decoration: underline; }
body.ptag-hub .pt-files__meta { color: var(--pt-text-faint); font-size: var(--pt-fs-xs); flex: none; white-space: nowrap; }
body.ptag-hub .pt-files__rm { flex: none; }
body.ptag-hub .pt-files__empty { color: var(--pt-text-mute); font-size: var(--pt-fs-sm); padding: 2px 2px 10px; }
body.ptag-hub .pt-files__bar { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 4px; }
body.ptag-hub .pt-files__hint { color: var(--pt-text-faint); font-size: var(--pt-fs-xs); }
@media (max-width: 560px) {
  body.ptag-hub .pt-files__item { flex-wrap: wrap; }
  body.ptag-hub .pt-files__meta { flex-basis: 100%; white-space: normal; }
}
/* == I30-ATTACHMENTS END == */

/* == I32-NAV-CAPS START (Jon: "the header menu ... needs to be in all caps".)
   text-transform rather than rewriting the labels, so the markup, the ng-class
   active logic and the aria text all stay as they are and this reverts in one
   line. Caps at the same size read cramped, so a little tracking comes with it.
   PRIMARY nav only - the profile dropdown stays sentence case, because caps
   inside a menu panel reads heavy. == */
body.ptag-hub .pt-nav .pt-nav__links a,
body.ptag-hub .pt-nav__mobile a:not(.pt-nav__alert) {
  text-transform: uppercase;
  letter-spacing: .07em;
}
/* == I32-NAV-CAPS END == */

/* == I33-LOCKED START (Jon: a cancelled or closed engagement must accept no more
   comments and no more attachments.) Reads as a neutral statement of fact, not
   an error: the request was not rejected, it is simply finished. Muted rather
   than red, and the record's whole history stays on screen above it. == */
body.ptag-hub .pt-locked {
  display: flex; align-items: flex-start; gap: 11px;
  margin: 4px 0 2px; padding: 13px 15px;
  background: var(--pt-surface-2);
  border: 1px solid var(--pt-stroke);
  border-left: 2px solid var(--pt-text-faint);
  border-radius: var(--pt-r-md);
}
body.ptag-hub .pt-locked .pt-i { color: var(--pt-text-faint); flex: none; margin-top: 2px; }
body.ptag-hub .pt-locked__t {
  font-size: var(--pt-fs-sm); font-weight: 600; color: var(--pt-text-hi); margin-bottom: 3px;
}
body.ptag-hub .pt-locked__s {
  font-size: var(--pt-fs-xs); color: var(--pt-text-mute); line-height: 1.6;
}
body.ptag-hub .pt-locked__s b { color: var(--pt-text); font-weight: 600; }
/* I34: the attachments-only variant sits inline above the composer rather than
   replacing it, so it is quieter than the full closed notice. */
body.ptag-hub .pt-locked--soft { margin: 2px 0 14px; padding: 11px 13px; }
/* == I33-LOCKED END == */


/* ==== I38 (2026-07-28): compact 'Where your requests stand' panel - the hero
   card ran too tall. Rows collapse to a single line; each state note now rides
   the row's title tooltip + aria-label (NOTES register in the landing client
   script is unchanged). Appended last so these win over the I12 row styles. ==== */
body.ptag-hub .pt-pipe__row { padding: 6px 10px; }
body.ptag-hub .pt-pipe__n { font-size: 16px; }
body.ptag-hub .pt-tracknum { margin-top: 10px; padding-top: 10px; }
body.ptag-hub .pt-tracknum__help { margin-top: 6px; }


/* ==== I40 (2026-07-28): full-bleed login page. SP scope-wraps widget css
   (.v<sys_id> prefix), so these ancestor resets must live here, where the
   injector delivers unscoped. Fenced to the login page by its page class:
   nothing else moves. ==== */
html.page-c5266396935e4f144639f8597bba104d main.padding-top { padding-top: 0 !important; }
html.page-c5266396935e4f144639f8597bba104d main .container-fluid { padding-left: 0 !important; padding-right: 0 !important; }


/* ==== I43 (2026-07-28): hold-to-reveal state notes on the pipe rows. The note
   sits collapsed inside the row (rest geometry identical to I38); a sustained
   hover (800ms transition-delay on the way IN only) slides the row open, and
   mouse-out collapses with zero delay. :focus-visible reveals at 150ms.
   The peek div is aria-hidden - the row's aria-label already speaks the note. ==== */
body.ptag-hub .pt-pipe__peek {
  max-height: 0; opacity: 0; overflow: hidden; margin-top: 0;
  font-size: var(--pt-fs-xs); line-height: 1.45; color: var(--pt-text);
  transition: max-height .22s var(--pt-ease) 0s, opacity .18s var(--pt-ease) 0s,
              margin-top .22s var(--pt-ease) 0s;
}
body.ptag-hub .pt-pipe__row:hover .pt-pipe__peek {
  max-height: 44px; opacity: .62; margin-top: 4px;
  transition: max-height .3s var(--pt-ease) .8s, opacity .3s var(--pt-ease) .84s,
              margin-top .3s var(--pt-ease) .8s;
}
body.ptag-hub .pt-pipe__row:focus-visible .pt-pipe__peek {
  max-height: 44px; opacity: .62; margin-top: 4px;
  transition-delay: .15s, .19s, .15s;
}
@media (prefers-reduced-motion: reduce) {
  body.ptag-hub .pt-pipe__peek,
  body.ptag-hub .pt-pipe__row:hover .pt-pipe__peek,
  body.ptag-hub .pt-pipe__row:focus-visible .pt-pipe__peek { transition: none; }
}


/* ==== I52 (2026-07-28): the timeline embed page renders LIGHT so the Lumen
   frame blends with the workspace record page. Fenced to that one page
   (I40 pattern) - every other ptag surface stays dark. ==== */
html.page-f3870fe693d243544639f8597bba10a8 body.ptag-hub { background: #ffffff; }

sp_widget.link:
function link(scope, element, attrs, controller) {
  try {
    var PTAG_FONTS = "/* PTAG Engagement Hub fonts. Lato is ServiceNow's own platform face (Next Experience / Polaris body, and the Horizon design system body face). Pulled from this instance's own /styles/polarisberg/fonts/lato/ and embedded as base64 so the portal keeps making zero external requests and does not depend on an undocumented static path that can move between releases. ServiceNow Sans, the 2025 brand face, is deliberately absent: it ships only on the marketing site, not on the platform, so it cannot be sourced from here. */@font-face{font-family:'Lato';font-style:normal;font-weight:300;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Lato';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Lato';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}@font-face{font-family:'Lato';font-style:italic;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}";
    var PTAG_TOKENS = "/* ============================================================\n   PTAG Engagement Hub \u2014 Design Tokens\n   Scope: everything hangs off body.ptag-hub (set by the invisible\n   ptag_global widget). Dark, premium, enterprise.\n   Brand DNA: PDS gradient #74C050 -> #00AEEF, ServiceNow green #63DF4E.\n   ============================================================ */\n\nbody.ptag-hub {\n  /* ---- Surfaces (dark grey ramp, never pure black) ---- */\n  --pt-bg-0: #0a0e16;          /* page background */\n  --pt-bg-1: #0d1320;          /* alternating section */\n  --pt-surface-1: #111927;     /* card */\n  --pt-surface-2: #16202f;     /* raised card / input */\n  --pt-surface-3: #1c2839;     /* hover / active surface */\n  --pt-glass: rgba(13, 19, 32, 0.72);\n  --pt-glass-light: rgba(22, 32, 47, 0.55);\n\n  /* ---- Strokes ---- */\n  --pt-stroke: rgba(148, 163, 184, 0.14);\n  --pt-stroke-strong: rgba(148, 163, 184, 0.28);\n  --pt-stroke-brand: rgba(99, 223, 78, 0.35);\n\n  /* ---- Text ---- */\n  --pt-text-hi: #edf2fa;\n  --pt-text: #c6d0e0;\n  --pt-text-mute: #8b98ad;\n  --pt-text-faint: #64748b;\n  --pt-text-invert: #07120a;\n\n  /* ---- Brand ---- */\n  --pt-green: #63df4e;         /* ServiceNow action green */\n  --pt-green-deep: #3fb637;\n  --pt-lime: #74c050;          /* PDS gradient start */\n  --pt-cyan: #00aeef;          /* PDS gradient end */\n  --pt-grad-brand: linear-gradient(105deg, var(--pt-lime) 0%, var(--pt-cyan) 100%);\n  --pt-grad-action: linear-gradient(180deg, #6fe75a 0%, #4ecf3a 100%);\n  --pt-grad-text: linear-gradient(92deg, #a7f29a 0%, #63df4e 34%, #00aeef 100%);\n  --pt-focus-ring: 0 0 0 3px rgba(99, 223, 78, 0.35);\n\n  /* ---- Lifecycle state colors (8 states) ---- */\n  --pt-state-submitted: #8fa3c8;\n  --pt-state-under_review: #f5b84c;\n  --pt-state-assessed: #38bdf8;\n  --pt-state-approved: #63df4e;\n  --pt-state-in_delivery: #a78bfa;\n  --pt-state-completed: #34d399;\n  --pt-state-declined: #f87171;\n  --pt-state-cancelled: #7c8798;\n  --pt-state-on_hold: #f5d0fe;\n\n  /* ---- Typography ---- */\n  --pt-font-ui: 'Lato', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n  --pt-font-display: 'Lato', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;\n  --pt-fs-xs: 12px;\n  --pt-fs-sm: 13.5px;\n  --pt-fs-base: 15px;\n  --pt-fs-md: 17px;\n  --pt-fs-lg: 20px;\n  --pt-fs-xl: 26px;\n  --pt-fs-2xl: 34px;\n  --pt-fs-3xl: 44px;\n  --pt-fs-hero: clamp(40px, 5.4vw, 66px);\n\n  /* ---- Spacing (4px base) ---- */\n  --pt-sp-1: 4px;  --pt-sp-2: 8px;   --pt-sp-3: 12px; --pt-sp-4: 16px;\n  --pt-sp-5: 20px; --pt-sp-6: 24px;  --pt-sp-7: 32px; --pt-sp-8: 40px;\n  --pt-sp-9: 48px; --pt-sp-10: 64px; --pt-sp-11: 80px; --pt-sp-12: 104px;\n\n  /* ---- Radius ---- */\n  --pt-r-sm: 8px; --pt-r-md: 12px; --pt-r-lg: 16px; --pt-r-xl: 22px; --pt-r-full: 999px;\n\n  /* ---- Elevation / glow ---- */\n  --pt-shadow-1: 0 1px 2px rgba(2, 6, 16, 0.5);\n  --pt-shadow-2: 0 12px 32px -8px rgba(2, 6, 16, 0.65);\n  --pt-shadow-3: 0 24px 64px -16px rgba(2, 6, 16, 0.8);\n  --pt-glow-green: 0 0 0 1px rgba(99, 223, 78, 0.28), 0 10px 42px -10px rgba(99, 223, 78, 0.4);\n  --pt-glow-cyan: 0 0 0 1px rgba(0, 174, 239, 0.25), 0 10px 42px -10px rgba(0, 174, 239, 0.35);\n\n  /* ---- Motion ---- */\n  --pt-ease: cubic-bezier(0.22, 0.61, 0.24, 1);\n  --pt-dur-fast: 160ms;\n  --pt-dur: 260ms;\n  --pt-dur-slow: 600ms;\n\n  /* ---- Layout ---- */\n  --pt-shell-max: 1200px;\n  --pt-nav-h: 68px;\n}\n";
    var PTAG_GLOBAL = "/* ============================================================\n   PTAG Engagement Hub \u2014 Global Stylesheet\n   Pairs with design-tokens.css. Injected by the invisible\n   ptag_global widget as <style id=\"ptag-global-css\">.\n   Everything scoped under body.ptag-hub so OOB portal pages\n   (login, etc.) are untouched.\n   ============================================================ */\n\n/* ---------- 0. Page base ---------- */\nbody.ptag-hub {\n  background: var(--pt-bg-0) !important;\n  color: var(--pt-text);\n  font-family: var(--pt-font-ui);\n  font-size: var(--pt-fs-base);\n  line-height: 1.6;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  overflow-x: hidden;\n}\nbody.ptag-hub ::selection { background: rgba(99, 223, 78, 0.3); color: var(--pt-text-hi); }\nbody.ptag-hub ::-webkit-scrollbar { width: 10px; height: 10px; }\nbody.ptag-hub ::-webkit-scrollbar-track { background: var(--pt-bg-0); }\nbody.ptag-hub ::-webkit-scrollbar-thumb { background: var(--pt-surface-3); border-radius: 8px; border: 2px solid var(--pt-bg-0); }\nbody.ptag-hub ::-webkit-scrollbar-thumb:hover { background: #263650; }\n\nbody.ptag-hub h1, body.ptag-hub h2, body.ptag-hub h3,\nbody.ptag-hub h4, body.ptag-hub h5 {\n  font-family: var(--pt-font-display);\n  color: var(--pt-text-hi);\n  letter-spacing: -0.015em;\n  margin: 0 0 var(--pt-sp-4);\n  line-height: 1.15;\n}\nbody.ptag-hub h1 { font-size: var(--pt-fs-3xl); font-weight: 700; }\nbody.ptag-hub h2 { font-size: var(--pt-fs-2xl); font-weight: 700; }\nbody.ptag-hub h3 { font-size: var(--pt-fs-xl); font-weight: 600; }\nbody.ptag-hub h4 { font-size: var(--pt-fs-lg); font-weight: 600; }\nbody.ptag-hub p { margin: 0 0 var(--pt-sp-4); }\nbody.ptag-hub a { color: var(--pt-green); text-decoration: none; transition: color var(--pt-dur-fast) var(--pt-ease); }\nbody.ptag-hub a:hover, body.ptag-hub a:focus { color: var(--pt-cyan); text-decoration: none; }\nbody.ptag-hub :focus { outline: none; }\nbody.ptag-hub a:focus-visible, body.ptag-hub button:focus-visible,\nbody.ptag-hub input:focus-visible, body.ptag-hub select:focus-visible,\nbody.ptag-hub textarea:focus-visible, body.ptag-hub [tabindex]:focus-visible {\n  box-shadow: var(--pt-focus-ring);\n  border-radius: var(--pt-r-sm);\n}\n\n/* ---------- 1. Bootstrap-3 / Service Portal neutralization (our pages only) ---------- */\nbody.ptag-hub .sp-page-root, body.ptag-hub #page, body.ptag-hub main { background: transparent; }\nbody.ptag-hub main .container, body.ptag-hub .sp-page-root .container { width: 100%; max-width: none; padding: 0; }\nbody.ptag-hub main .row { margin-left: 0; margin-right: 0; }\nbody.ptag-hub main [class^=\"col-\"], body.ptag-hub main [class*=\" col-\"] { padding-left: 0; padding-right: 0; }\nbody.ptag-hub .panel, body.ptag-hub .panel-default { background: transparent; border: 0; box-shadow: none; }\n\n/* Hide usage-insights / analytics affordances everywhere on our pages */\nbody.ptag-hub button.uxa-analytics-btn,\nbody.ptag-hub .uxa-analytics-btn,\nbody.ptag-hub [class*=\"uxa-analytics\"] { display: none !important; }\n\n/* ---------- 2. Layout primitives ---------- */\nbody.ptag-hub .pt-shell { max-width: var(--pt-shell-max); margin: 0 auto; padding: 0 28px; }\nbody.ptag-hub .pt-section { padding: var(--pt-sp-11) 0; position: relative; }\nbody.ptag-hub .pt-section--tight { padding: var(--pt-sp-8) 0; }\nbody.ptag-hub .pt-section--alt { background: var(--pt-bg-1); border-top: 1px solid var(--pt-stroke); border-bottom: 1px solid var(--pt-stroke); }\nbody.ptag-hub .pt-center { text-align: center; }\nbody.ptag-hub .pt-muted { color: var(--pt-text-mute); }\nbody.ptag-hub .pt-faint { color: var(--pt-text-faint); }\nbody.ptag-hub .pt-eyebrow {\n  display: inline-flex; align-items: center; gap: 8px;\n  font-size: var(--pt-fs-xs); font-weight: 700; letter-spacing: 0.14em;\n  text-transform: uppercase; color: var(--pt-green);\n  padding: 6px 14px; border-radius: var(--pt-r-full);\n  background: rgba(99, 223, 78, 0.08); border: 1px solid rgba(99, 223, 78, 0.22);\n}\nbody.ptag-hub .pt-grad-text {\n  background: var(--pt-grad-text);\n  -webkit-background-clip: text; background-clip: text;\n  -webkit-text-fill-color: transparent; color: transparent;\n}\nbody.ptag-hub .pt-flex { display: flex; align-items: center; gap: var(--pt-sp-4); }\nbody.ptag-hub .pt-flex--between { justify-content: space-between; }\nbody.ptag-hub .pt-flex--wrap { flex-wrap: wrap; }\n\n/* ---------- 3. Atmosphere (orbs + noise + grid) ---------- */\nbody.ptag-hub .pt-atmo { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }\nbody.ptag-hub .pt-atmo::before {\n  content: \"\"; position: absolute; inset: -20%;\n  background:\n    radial-gradient(560px 420px at 12% 8%, rgba(116, 192, 80, 0.14), transparent 62%),\n    radial-gradient(680px 480px at 88% 18%, rgba(0, 174, 239, 0.13), transparent 64%),\n    radial-gradient(520px 520px at 55% 110%, rgba(99, 223, 78, 0.07), transparent 60%);\n}\nbody.ptag-hub .pt-atmo::after {\n  content: \"\"; position: absolute; inset: 0; opacity: 0.5;\n  background-image: url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2'/><feColorMatrix type='saturate' values='0'/></filter><rect width='160' height='160' filter='url(%23n)' opacity='0.05'/></svg>\");\n}\nbody.ptag-hub .pt-gridlines {\n  position: absolute; inset: 0; pointer-events: none;\n  background-image:\n    linear-gradient(rgba(148, 163, 184, 0.05) 1px, transparent 1px),\n    linear-gradient(90deg, rgba(148, 163, 184, 0.05) 1px, transparent 1px);\n  background-size: 56px 56px;\n  -webkit-mask-image: radial-gradient(ellipse 90% 70% at 50% 0%, #000 30%, transparent 78%);\n  mask-image: radial-gradient(ellipse 90% 70% at 50% 0%, #000 30%, transparent 78%);\n}\n\n/* ---------- 4. Navigation ---------- */\nbody.ptag-hub .pt-nav {\n  position: sticky; top: 0; z-index: 80;\n  height: var(--pt-nav-h);\n  border-bottom: 1px solid transparent;\n  transition: background var(--pt-dur) var(--pt-ease), border-color var(--pt-dur) var(--pt-ease);\n}\nbody.ptag-hub .pt-nav.is-scrolled {\n  background: var(--pt-glass);\n  -webkit-backdrop-filter: blur(18px) saturate(1.5);\n  backdrop-filter: blur(18px) saturate(1.5);\n  border-bottom-color: var(--pt-stroke);\n}\nbody.ptag-hub .pt-nav__inner { height: var(--pt-nav-h); display: flex; align-items: center; justify-content: space-between; gap: var(--pt-sp-6); }\nbody.ptag-hub .pt-nav__brand { display: flex; align-items: center; gap: 14px; }\nbody.ptag-hub .pt-nav__brand svg, body.ptag-hub .pt-nav__brand img { height: 24px; width: auto; display: block; }\nbody.ptag-hub .pt-nav__divider { width: 1px; height: 22px; background: var(--pt-stroke-strong); }\nbody.ptag-hub .pt-nav__links { display: flex; align-items: center; gap: 4px; }\nbody.ptag-hub .pt-nav__links a {\n  padding: 9px 14px; border-radius: var(--pt-r-sm);\n  color: var(--pt-text-mute); font-size: var(--pt-fs-sm); font-weight: 600;\n  transition: all var(--pt-dur-fast) var(--pt-ease);\n}\nbody.ptag-hub .pt-nav__links a:hover { color: var(--pt-text-hi); background: var(--pt-surface-3); }\nbody.ptag-hub .pt-nav__links a.is-active { color: var(--pt-green); background: rgba(99, 223, 78, 0.09); }\nbody.ptag-hub .pt-nav__user {\n  display: inline-flex; align-items: center; gap: 10px;\n  padding: 6px 14px 6px 6px; border-radius: var(--pt-r-full);\n  background: var(--pt-surface-2); border: 1px solid var(--pt-stroke);\n  color: var(--pt-text); font-size: var(--pt-fs-sm); font-weight: 600;\n}\nbody.ptag-hub .pt-avatar {\n  width: 30px; height: 30px; border-radius: 50%;\n  display: inline-flex; align-items: center; justify-content: center;\n  background: var(--pt-grad-brand); color: var(--pt-text-invert);\n  font-size: 12px; font-weight: 800; letter-spacing: 0.02em;\n}\n\n/* ---------- 5. Buttons ---------- */\nbody.ptag-hub .pt-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 9px;\n  padding: 12px 22px; border-radius: var(--pt-r-md);\n  font-family: var(--pt-font-ui); font-size: var(--pt-fs-base); font-weight: 700;\n  border: 1px solid transparent; cursor: pointer; white-space: nowrap;\n  transition: transform var(--pt-dur-fast) var(--pt-ease), box-shadow var(--pt-dur) var(--pt-ease),\n              background var(--pt-dur-fast) var(--pt-ease), border-color var(--pt-dur-fast) var(--pt-ease),\n              color var(--pt-dur-fast) var(--pt-ease);\n  text-decoration: none;\n}\nbody.ptag-hub .pt-btn:active { transform: translateY(1px); }\nbody.ptag-hub .pt-btn--primary { background: var(--pt-grad-action); color: var(--pt-text-invert) !important; }\nbody.ptag-hub .pt-btn--primary:hover { box-shadow: var(--pt-glow-green); transform: translateY(-1px); color: var(--pt-text-invert); }\nbody.ptag-hub .pt-btn--ghost { background: transparent; border-color: var(--pt-stroke-strong); color: var(--pt-text-hi) !important; }\nbody.ptag-hub .pt-btn--ghost:hover { background: var(--pt-surface-3); border-color: var(--pt-stroke-brand); }\nbody.ptag-hub .pt-btn--subtle { background: var(--pt-surface-2); border-color: var(--pt-stroke); color: var(--pt-text) !important; }\nbody.ptag-hub .pt-btn--subtle:hover { background: var(--pt-surface-3); color: var(--pt-text-hi) !important; }\nbody.ptag-hub .pt-btn--lg { padding: 15px 30px; font-size: var(--pt-fs-md); border-radius: 14px; }\nbody.ptag-hub .pt-btn--sm { padding: 8px 14px; font-size: var(--pt-fs-sm); border-radius: 10px; }\nbody.ptag-hub .pt-btn[disabled], body.ptag-hub .pt-btn.is-disabled {\n  opacity: 0.45; pointer-events: none;\n}\nbody.ptag-hub .pt-btn .pt-i { flex: none; }\n\n/* ---------- 6. Forms ---------- */\nbody.ptag-hub .pt-field { margin-bottom: var(--pt-sp-5); }\nbody.ptag-hub .pt-field > label {\n  display: block; margin-bottom: 8px;\n  font-size: var(--pt-fs-xs); font-weight: 700; letter-spacing: 0.1em;\n  text-transform: uppercase; color: var(--pt-text-mute);\n}\nbody.ptag-hub .pt-field .pt-req { color: var(--pt-green); }\nbody.ptag-hub .pt-input, body.ptag-hub .pt-select, body.ptag-hub .pt-textarea,\nbody.ptag-hub .pt-field input[type=\"text\"], body.ptag-hub .pt-field input[type=\"number\"],\nbody.ptag-hub .pt-field input[type=\"email\"], body.ptag-hub .pt-field select,\nbody.ptag-hub .pt-field textarea {\n  display: block; width: 100%;\n  background: var(--pt-surface-2); color: var(--pt-text-hi);\n  border: 1px solid var(--pt-stroke); border-radius: var(--pt-r-md);\n  padding: 12px 15px; font-family: var(--pt-font-ui); font-size: var(--pt-fs-base);\n  transition: border-color var(--pt-dur-fast) var(--pt-ease), box-shadow var(--pt-dur-fast) var(--pt-ease);\n  -webkit-appearance: none; appearance: none; box-shadow: none; height: auto;\n}\nbody.ptag-hub .pt-field textarea { min-height: 120px; resize: vertical; }\nbody.ptag-hub .pt-field select {\n  background-image: url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='%238b98ad' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='m6 9 6 6 6-6'/></svg>\");\n  background-repeat: no-repeat; background-position: right 14px center; padding-right: 40px;\n}\nbody.ptag-hub .pt-field select option { background: var(--pt-surface-2); color: var(--pt-text-hi); }\nbody.ptag-hub .pt-field input:focus, body.ptag-hub .pt-field select:focus,\nbody.ptag-hub .pt-field textarea:focus {\n  border-color: var(--pt-green); box-shadow: var(--pt-focus-ring); outline: none;\n}\nbody.ptag-hub .pt-field input::placeholder, body.ptag-hub .pt-field textarea::placeholder { color: var(--pt-text-faint); }\nbody.ptag-hub .pt-field.has-error input, body.ptag-hub .pt-field.has-error select,\nbody.ptag-hub .pt-field.has-error textarea { border-color: var(--pt-state-declined); }\nbody.ptag-hub .pt-field__err { margin-top: 6px; font-size: var(--pt-fs-sm); color: var(--pt-state-declined); }\nbody.ptag-hub .pt-field__hint { margin-top: 6px; font-size: var(--pt-fs-sm); color: var(--pt-text-faint); }\nbody.ptag-hub .pt-check {\n  display: flex; align-items: flex-start; gap: 12px; padding: 14px 16px;\n  background: var(--pt-surface-2); border: 1px solid var(--pt-stroke);\n  border-radius: var(--pt-r-md); cursor: pointer; margin-bottom: 10px;\n  transition: border-color var(--pt-dur-fast) var(--pt-ease), background var(--pt-dur-fast) var(--pt-ease);\n}\nbody.ptag-hub .pt-check:hover { border-color: var(--pt-stroke-strong); }\nbody.ptag-hub .pt-check input[type=\"checkbox\"] {\n  width: 18px; height: 18px; margin: 2px 0 0; flex: none;\n  accent-color: var(--pt-green); cursor: pointer;\n}\nbody.ptag-hub .pt-check.is-on { border-color: var(--pt-stroke-brand); background: rgba(99, 223, 78, 0.05); }\nbody.ptag-hub .pt-check b { color: var(--pt-text-hi); display: block; font-size: var(--pt-fs-base); }\nbody.ptag-hub .pt-check span { color: var(--pt-text-mute); font-size: var(--pt-fs-sm); }\nbody.ptag-hub .pt-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 var(--pt-sp-5); }\nbody.ptag-hub .pt-form-grid .pt-field--full { grid-column: 1 / -1; }\n\n/* ---------- 7. Cards + bento ---------- */\nbody.ptag-hub .pt-card {\n  background: var(--pt-surface-1); border: 1px solid var(--pt-stroke);\n  border-radius: var(--pt-r-lg); padding: var(--pt-sp-6);\n  box-shadow: var(--pt-shadow-1);\n  transition: transform var(--pt-dur) var(--pt-ease), border-color var(--pt-dur) var(--pt-ease), box-shadow var(--pt-dur) var(--pt-ease);\n}\nbody.ptag-hub .pt-card--hover:hover { transform: translateY(-3px); border-color: var(--pt-stroke-strong); box-shadow: var(--pt-shadow-2); }\nbody.ptag-hub .pt-card--glass {\n  background: var(--pt-glass-light);\n  -webkit-backdrop-filter: blur(16px) saturate(1.4); backdrop-filter: blur(16px) saturate(1.4);\n}\nbody.ptag-hub .pt-card--pad-lg { padding: var(--pt-sp-8); }\nbody.ptag-hub .pt-icon-tile {\n  width: 44px; height: 44px; border-radius: var(--pt-r-md); flex: none;\n  display: inline-flex; align-items: center; justify-content: center;\n  background: rgba(99, 223, 78, 0.11); color: var(--pt-green);\n  border: 1px solid rgba(99, 223, 78, 0.2); margin-bottom: var(--pt-sp-4);\n}\nbody.ptag-hub .pt-icon-tile--cyan { background: rgba(0, 174, 239, 0.11); color: var(--pt-cyan); border-color: rgba(0, 174, 239, 0.2); }\nbody.ptag-hub .pt-icon-tile--violet { background: rgba(167, 139, 250, 0.11); color: var(--pt-state-in_delivery); border-color: rgba(167, 139, 250, 0.2); }\nbody.ptag-hub .pt-bento { display: grid; grid-template-columns: repeat(12, 1fr); gap: 20px; }\nbody.ptag-hub .pt-b-3 { grid-column: span 3; }\nbody.ptag-hub .pt-b-4 { grid-column: span 4; }\nbody.ptag-hub .pt-b-6 { grid-column: span 6; }\nbody.ptag-hub .pt-b-8 { grid-column: span 8; }\nbody.ptag-hub .pt-b-12 { grid-column: span 12; }\n\n/* ---------- 8. State chips ---------- */\nbody.ptag-hub .pt-chip {\n  display: inline-flex; align-items: center; gap: 7px;\n  padding: 4px 12px; border-radius: var(--pt-r-full);\n  font-size: var(--pt-fs-xs); font-weight: 700; letter-spacing: 0.03em;\n  border: 1px solid; white-space: nowrap;\n}\nbody.ptag-hub .pt-chip::before { content: \"\"; width: 7px; height: 7px; border-radius: 50%; background: currentColor; box-shadow: 0 0 8px currentColor; }\nbody.ptag-hub .pt-chip[data-state=\"submitted\"]     { color: var(--pt-state-submitted);     background: rgba(143,163,200,0.1);  border-color: rgba(143,163,200,0.3); }\nbody.ptag-hub .pt-chip[data-state=\"under_review\"]  { color: var(--pt-state-under_review);  background: rgba(245,184,76,0.1);   border-color: rgba(245,184,76,0.3); }\nbody.ptag-hub .pt-chip[data-state=\"assessed\"]      { color: var(--pt-state-assessed);      background: rgba(56,189,248,0.1);   border-color: rgba(56,189,248,0.3); }\nbody.ptag-hub .pt-chip[data-state=\"approved\"]      { color: var(--pt-state-approved);      background: rgba(99,223,78,0.1);    border-color: rgba(99,223,78,0.3); }\nbody.ptag-hub .pt-chip[data-state=\"in_delivery\"]   { color: var(--pt-state-in_delivery);   background: rgba(167,139,250,0.1);  border-color: rgba(167,139,250,0.3); }\nbody.ptag-hub .pt-chip[data-state=\"completed\"]     { color: var(--pt-state-completed);     background: rgba(52,211,153,0.1);   border-color: rgba(52,211,153,0.3); }\nbody.ptag-hub .pt-chip[data-state=\"declined\"]      { color: var(--pt-state-declined);      background: rgba(248,113,113,0.1);  border-color: rgba(248,113,113,0.3); }\nbody.ptag-hub .pt-chip[data-state=\"cancelled\"]     { color: var(--pt-state-cancelled);     background: rgba(124,135,152,0.1);  border-color: rgba(124,135,152,0.3); }\n\n/* ---------- 9. Hero ---------- */\nbody.ptag-hub .pt-hero { position: relative; padding: var(--pt-sp-12) 0 var(--pt-sp-10); overflow: hidden; }\nbody.ptag-hub .pt-hero__grid { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr); gap: var(--pt-sp-10); align-items: center; position: relative; }\nbody.ptag-hub .pt-hero__title { font-size: var(--pt-fs-hero); font-weight: 700; letter-spacing: -0.025em; line-height: 1.06; margin: var(--pt-sp-5) 0; }\nbody.ptag-hub .pt-hero__sub { font-size: var(--pt-fs-md); color: var(--pt-text-mute); max-width: 560px; margin-bottom: var(--pt-sp-7); }\nbody.ptag-hub .pt-hero__cta { display: flex; gap: var(--pt-sp-4); flex-wrap: wrap; align-items: center; }\nbody.ptag-hub .pt-hero__note { font-size: var(--pt-fs-sm); color: var(--pt-text-faint); margin-top: var(--pt-sp-4); }\nbody.ptag-hub .pt-hero__panel { position: relative; }\nbody.ptag-hub .pt-hero__panel .pt-card { box-shadow: var(--pt-shadow-3); }\nbody.ptag-hub .pt-hero__panel::before {\n  content: \"\"; position: absolute; inset: -12% -8%;\n  background: radial-gradient(60% 60% at 50% 40%, rgba(0, 174, 239, 0.14), transparent 70%);\n  pointer-events: none;\n}\n\n/* ---------- 10. Stats ---------- */\nbody.ptag-hub .pt-stats-strip {\n  display: grid; grid-template-columns: repeat(4, 1fr);\n  border: 1px solid var(--pt-stroke); border-radius: var(--pt-r-lg);\n  background: var(--pt-surface-1); overflow: hidden;\n}\nbody.ptag-hub .pt-stat { padding: var(--pt-sp-6); border-left: 1px solid var(--pt-stroke); }\nbody.ptag-hub .pt-stat:first-child { border-left: 0; }\nbody.ptag-hub .pt-stat__num {\n  font-family: var(--pt-font-display); font-weight: 700;\n  font-size: var(--pt-fs-2xl); color: var(--pt-text-hi);\n  font-variant-numeric: tabular-nums; line-height: 1.1;\n}\nbody.ptag-hub .pt-stat__label { font-size: var(--pt-fs-sm); color: var(--pt-text-mute); margin-top: 4px; font-weight: 600; }\n\n/* ---------- 11. Multi-step form ---------- */\nbody.ptag-hub .pt-steps { display: flex; gap: var(--pt-sp-2); margin-bottom: var(--pt-sp-7); }\nbody.ptag-hub .pt-step { flex: 1; text-align: left; position: relative; padding-top: 14px; }\nbody.ptag-hub .pt-step::before {\n  content: \"\"; position: absolute; top: 0; left: 0; right: 0; height: 4px;\n  border-radius: var(--pt-r-full); background: var(--pt-surface-3);\n  transition: background var(--pt-dur) var(--pt-ease);\n}\nbody.ptag-hub .pt-step.is-done::before { background: var(--pt-green-deep); }\nbody.ptag-hub .pt-step.is-active::before { background: var(--pt-grad-brand); }\nbody.ptag-hub .pt-step__k { font-size: var(--pt-fs-xs); font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--pt-text-faint); }\nbody.ptag-hub .pt-step__t { font-size: var(--pt-fs-sm); font-weight: 700; color: var(--pt-text-mute); margin-top: 2px; }\nbody.ptag-hub .pt-step.is-active .pt-step__t, body.ptag-hub .pt-step.is-active .pt-step__k { color: var(--pt-text-hi); }\nbody.ptag-hub .pt-step.is-done .pt-step__t { color: var(--pt-green); }\nbody.ptag-hub .pt-review { border: 1px solid var(--pt-stroke); border-radius: var(--pt-r-md); overflow: hidden; }\nbody.ptag-hub .pt-review__row { display: grid; grid-template-columns: 220px 1fr; gap: var(--pt-sp-4); padding: 13px 18px; border-top: 1px solid var(--pt-stroke); background: var(--pt-surface-1); }\nbody.ptag-hub .pt-review__row:first-child { border-top: 0; }\nbody.ptag-hub .pt-review__k { color: var(--pt-text-mute); font-size: var(--pt-fs-sm); font-weight: 600; }\nbody.ptag-hub .pt-review__v { color: var(--pt-text-hi); font-size: var(--pt-fs-sm); word-break: break-word; }\n\n/* ---------- 12. Success / token panel ---------- */\nbody.ptag-hub .pt-success { text-align: center; padding: var(--pt-sp-9) var(--pt-sp-6); }\nbody.ptag-hub .pt-success__ring {\n  width: 72px; height: 72px; margin: 0 auto var(--pt-sp-5); border-radius: 50%;\n  display: flex; align-items: center; justify-content: center;\n  background: rgba(99, 223, 78, 0.12); border: 1px solid rgba(99, 223, 78, 0.4);\n  color: var(--pt-green); box-shadow: var(--pt-glow-green);\n}\nbody.ptag-hub .pt-token {\n  display: inline-flex; align-items: center; gap: 10px;\n  padding: 10px 16px; margin-top: var(--pt-sp-4);\n  background: var(--pt-surface-2); border: 1px dashed var(--pt-stroke-strong);\n  border-radius: var(--pt-r-md); font-family: var(--pt-font-display);\n  font-size: var(--pt-fs-sm); color: var(--pt-cyan); letter-spacing: 0.04em;\n  word-break: break-all;\n}\n\n/* ---------- 13. Timeline (tracker) ---------- */\nbody.ptag-hub .pt-timeline { position: relative; padding-left: 6px; }\nbody.ptag-hub .pt-tl-item { position: relative; display: grid; grid-template-columns: 26px 1fr; gap: var(--pt-sp-4); padding-bottom: var(--pt-sp-6); }\nbody.ptag-hub .pt-tl-item::before {\n  content: \"\"; position: absolute; left: 12px; top: 26px; bottom: 2px; width: 2px;\n  background: var(--pt-surface-3);\n}\nbody.ptag-hub .pt-tl-item:last-child::before { display: none; }\nbody.ptag-hub .pt-tl-node {\n  width: 26px; height: 26px; border-radius: 50%; z-index: 1;\n  display: flex; align-items: center; justify-content: center;\n  background: var(--pt-surface-2); border: 2px solid var(--pt-surface-3);\n  color: transparent; transition: all var(--pt-dur) var(--pt-ease);\n}\nbody.ptag-hub .pt-tl-item.is-done .pt-tl-node { background: var(--pt-green-deep); border-color: var(--pt-green-deep); color: var(--pt-text-invert); }\nbody.ptag-hub .pt-tl-item.is-done::before { background: var(--pt-green-deep); }\nbody.ptag-hub .pt-tl-item.is-current .pt-tl-node {\n  background: var(--pt-surface-1); border-color: var(--pt-green); color: var(--pt-green);\n  animation: pt-pulse 2.2s var(--pt-ease) infinite;\n}\nbody.ptag-hub .pt-tl-item.is-negative .pt-tl-node { background: rgba(248,113,113,0.15); border-color: var(--pt-state-declined); color: var(--pt-state-declined); }\nbody.ptag-hub .pt-tl-title { font-weight: 700; color: var(--pt-text-hi); font-size: var(--pt-fs-base); }\nbody.ptag-hub .pt-tl-item.is-future .pt-tl-title { color: var(--pt-text-faint); font-weight: 600; }\nbody.ptag-hub .pt-tl-sub { font-size: var(--pt-fs-sm); color: var(--pt-text-mute); margin-top: 2px; }\n@keyframes pt-pulse {\n  0% { box-shadow: 0 0 0 0 rgba(99, 223, 78, 0.4); }\n  70% { box-shadow: 0 0 0 12px rgba(99, 223, 78, 0); }\n  100% { box-shadow: 0 0 0 0 rgba(99, 223, 78, 0); }\n}\n\n/* ---------- 14. Row cards (My Engagements) ---------- */\nbody.ptag-hub .pt-rowcard {\n  display: flex; align-items: center; justify-content: space-between; gap: var(--pt-sp-5);\n  padding: 18px 22px; margin-bottom: 12px;\n  background: var(--pt-surface-1); border: 1px solid var(--pt-stroke);\n  border-radius: var(--pt-r-lg);\n  transition: transform var(--pt-dur-fast) var(--pt-ease), border-color var(--pt-dur-fast) var(--pt-ease), box-shadow var(--pt-dur) var(--pt-ease);\n}\nbody.ptag-hub .pt-rowcard:hover { transform: translateY(-2px); border-color: var(--pt-stroke-strong); box-shadow: var(--pt-shadow-2); }\nbody.ptag-hub .pt-rowcard__num { font-family: var(--pt-font-display); font-weight: 700; color: var(--pt-green); font-size: var(--pt-fs-sm); letter-spacing: 0.04em; }\nbody.ptag-hub .pt-rowcard__t { color: var(--pt-text-hi); font-weight: 700; font-size: var(--pt-fs-md); margin: 2px 0; }\nbody.ptag-hub .pt-rowcard__meta { font-size: var(--pt-fs-sm); color: var(--pt-text-mute); }\nbody.ptag-hub .pt-rowcard__right { display: flex; align-items: center; gap: var(--pt-sp-5); flex: none; }\n\n/* ---------- 15. Skeletons + empty states ---------- */\nbody.ptag-hub .pt-skel { position: relative; overflow: hidden; background: var(--pt-surface-2); border-radius: var(--pt-r-md); min-height: 16px; }\nbody.ptag-hub .pt-skel::after {\n  content: \"\"; position: absolute; inset: 0;\n  background: linear-gradient(90deg, transparent, rgba(148, 163, 184, 0.09), transparent);\n  transform: translateX(-100%); animation: pt-shimmer 1.4s infinite;\n}\n@keyframes pt-shimmer { 100% { transform: translateX(100%); } }\nbody.ptag-hub .pt-empty { text-align: center; padding: var(--pt-sp-10) var(--pt-sp-6); }\nbody.ptag-hub .pt-empty .pt-icon-tile { margin: 0 auto var(--pt-sp-4); }\nbody.ptag-hub .pt-empty__t { color: var(--pt-text-hi); font-weight: 700; font-size: var(--pt-fs-lg); font-family: var(--pt-font-display); }\nbody.ptag-hub .pt-empty__s { color: var(--pt-text-mute); max-width: 420px; margin: 8px auto 0; }\n\n/* ---------- 16. Icons ---------- */\nbody.ptag-hub .pt-i { width: 20px; height: 20px; flex: none; }\nbody.ptag-hub .pt-i--sm { width: 16px; height: 16px; }\nbody.ptag-hub .pt-i--lg { width: 24px; height: 24px; }\nbody.ptag-hub .pt-spin { animation: pt-rot 0.9s linear infinite; }\n@keyframes pt-rot { 100% { transform: rotate(360deg); } }\n\n/* ---------- 17. Footer ---------- */\nbody.ptag-hub .pt-footer { border-top: 1px solid var(--pt-stroke); background: var(--pt-bg-1); padding: var(--pt-sp-9) 0 var(--pt-sp-7); margin-top: var(--pt-sp-11); }\nbody.ptag-hub .pt-footer__brand { display: flex; align-items: center; gap: 16px; margin-bottom: var(--pt-sp-5); }\nbody.ptag-hub .pt-footer__brand svg, body.ptag-hub .pt-footer__brand img { height: 20px; width: auto; opacity: 0.85; }\nbody.ptag-hub .pt-footer__links { display: flex; gap: var(--pt-sp-5); flex-wrap: wrap; }\nbody.ptag-hub .pt-footer__links a { color: var(--pt-text-mute); font-size: var(--pt-fs-sm); font-weight: 600; }\nbody.ptag-hub .pt-footer__links a:hover { color: var(--pt-text-hi); }\nbody.ptag-hub .pt-footer__fine { margin-top: var(--pt-sp-5); font-size: var(--pt-fs-xs); color: var(--pt-text-faint); }\n\n/* ---------- 18. Reveal motion ---------- */\nbody.ptag-hub .pt-reveal { opacity: 0; transform: translateY(18px); transition: opacity var(--pt-dur-slow) var(--pt-ease), transform var(--pt-dur-slow) var(--pt-ease); will-change: opacity, transform; }\nbody.ptag-hub .pt-reveal.is-in { opacity: 1; transform: none; }\n\n/* ---------- 19. Responsive ---------- */\n@media (max-width: 1024px) {\n  body.ptag-hub .pt-hero__grid { grid-template-columns: 1fr; gap: var(--pt-sp-8); }\n  body.ptag-hub .pt-b-3, body.ptag-hub .pt-b-4 { grid-column: span 6; }\n  body.ptag-hub .pt-b-8, body.ptag-hub .pt-b-6 { grid-column: span 12; }\n  body.ptag-hub .pt-stats-strip { grid-template-columns: repeat(2, 1fr); }\n  body.ptag-hub .pt-stat:nth-child(3) { border-left: 0; }\n  body.ptag-hub .pt-stat { border-top: 1px solid var(--pt-stroke); }\n  body.ptag-hub .pt-stat:nth-child(-n+2) { border-top: 0; }\n}\n@media (max-width: 760px) {\n  body.ptag-hub .pt-shell { padding: 0 18px; }\n  body.ptag-hub .pt-section { padding: var(--pt-sp-9) 0; }\n  body.ptag-hub .pt-b-3, body.ptag-hub .pt-b-4 { grid-column: span 12; }\n  body.ptag-hub .pt-nav__links { display: none; }\n  body.ptag-hub .pt-form-grid { grid-template-columns: 1fr; }\n  body.ptag-hub .pt-rowcard { flex-direction: column; align-items: flex-start; gap: var(--pt-sp-3); }\n  body.ptag-hub .pt-review__row { grid-template-columns: 1fr; gap: 2px; }\n  body.ptag-hub .pt-steps { flex-direction: column; gap: 10px; }\n  body.ptag-hub .pt-step { padding-top: 0; padding-left: 14px; }\n  body.ptag-hub .pt-step::before { top: 0; bottom: 0; left: 0; right: auto; width: 4px; height: auto; }\n}\n\n/* ---------- 20. Reduced motion ---------- */\n@media (prefers-reduced-motion: reduce) {\n  body.ptag-hub *, body.ptag-hub *::before, body.ptag-hub *::after {\n    animation-duration: 0.01ms !important; animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important; scroll-behavior: auto !important;\n  }\n  body.ptag-hub .pt-reveal { opacity: 1; transform: none; }\n}\n";
