    var b = document.body;
    if (!/\bptag-hub\b/.test(b.className)) { b.className += ' ptag-hub'; }
    function put(id, css) {
      if (document.getElementById(id)) return;
      var s = document.createElement('style'); s.id = id; s.type = 'text/css';
      s.appendChild(document.createTextNode(css));
      document.head.appendChild(s);
    }
    put('ptag-fonts-css', PTAG_FONTS);
    put('ptag-tokens-css', PTAG_TOKENS);
    put('ptag-global-css', PTAG_GLOBAL);
    try { document.documentElement.classList.add('pt-booted'); } catch (eBoot) {}
    if (!document.getElementById('ptag-sprite')) {
      var d = document.createElement('div'); d.id = 'ptag-sprite';
      d.style.display = 'none'; d.setAttribute('aria-hidden', 'true');
      d.innerHTML = PTAG_SPRITE; b.appendChild(d);
    }
    // belt-and-braces usage-insights removal (CSS rule also present)
    var kills = 0; var killer = setInterval(function () {
      var els = document.querySelectorAll('.uxa-analytics-btn, [class*="uxa-analytics"]');
      for (var i = 0; i < els.length; i++) { els[i].parentNode && els[i].parentNode.removeChild(els[i]); }
      if (++kills > 20) clearInterval(killer);
    }, 700);
    // ---- motion.js (inlined) ----
/* ============================================================
   PTAG Engagement Hub — motion.js (vanilla, no dependencies)
   Master copy. Ships inside the ptag_global widget link function.
   Behaviors:
     1. .pt-reveal        -> adds .is-in when scrolled into view
                             (stagger via [data-delay] ms attr)
     2. .pt-count[data-to] -> counts numerals up on first reveal
     3. nav scroll state   -> .pt-nav gets .is-scrolled past 12px
   Honors prefers-reduced-motion (everything appears instantly).
   ============================================================ */
(function ptagMotion() {
  'use strict';
  var reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function countUp(el) {
    var to = parseFloat(el.getAttribute('data-to') || '0');
    var suffix = el.getAttribute('data-suffix') || '';
    if (reduced || !window.requestAnimationFrame) { el.textContent = to + suffix; return; }
    var dur = 1100, t0 = null;
    function step(ts) {
      if (!t0) t0 = ts;
      var p = Math.min((ts - t0) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = Math.round(to * eased) + suffix;
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  function init() {
    var revealables = document.querySelectorAll('.pt-reveal:not(.is-bound)');
    if (reduced || !('IntersectionObserver' in window)) {
      Array.prototype.forEach.call(revealables, function (el) {
        el.classList.add('is-bound', 'is-in');
        if (el.classList.contains('pt-count')) countUp(el);
        Array.prototype.forEach.call(el.querySelectorAll('.pt-count'), countUp);
      });
      return;
    }
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (en) {
        if (!en.isIntersecting) return;
        var el = en.target;
        var d = parseInt(el.getAttribute('data-delay') || '0', 10);
        setTimeout(function () {
          el.classList.add('is-in');
          if (el.classList.contains('pt-count')) countUp(el);
          Array.prototype.forEach.call(el.querySelectorAll('.pt-count'), countUp);
        }, d);
        io.unobserve(el);
      });
    }, { threshold: 0.14, rootMargin: '0px 0px -40px 0px' });
    Array.prototype.forEach.call(revealables, function (el) {
      el.classList.add('is-bound');
      io.observe(el);
    });
  }

  function navState() {
    var nav = document.querySelector('.pt-nav');
    if (!nav) return;
    var on = function () {
      nav.classList.toggle('is-scrolled', (window.pageYOffset || 0) > 12);
    };
    window.addEventListener('scroll', on, { passive: true });
    on();
  }

  // SP swaps page content via Angular; re-scan on interval-lite + first paint.
  init(); navState();
  var scans = 0;
  var t = setInterval(function () {
    init(); navState();
    if (++scans > 20) clearInterval(t); // first ~10s covers page hydration
  }, 500);
  document.addEventListener('click', function () { setTimeout(init, 350); }, true);
})();

  } catch (e) { /* never break the page */ }
}
